   ========================================================================== */
var Diag = (function () {
  var TOPIC = 'iptvdiag-mb7k2q9x';
  var sent = {};
  function send(tag, msg) {
    if (sent[tag] || !window.CONFIG || !CONFIG.relay) return;
    sent[tag] = true;
    try {
      var x = new XMLHttpRequest();
      x.open('POST', CONFIG.relay + '/' + TOPIC, true);
      x.setRequestHeader('Content-Type', 'text/plain');
      x.send('[' + tag + '] ' + msg);
