      url += '&' + k + '=' + encodeURIComponent(params[k]);
    }
    return url;
  }

  function errorText(err) {
    if (!err) return '';
    switch (err.code) {
      case 'timeout': return 'السيرفر لا يستجيب (انتهت المهلة)';
      case 'network': return 'تعذّر الاتصال بالسيرفر، تأكد من الرابط والإنترنت';
      case 'http': return 'خطأ من السيرفر (' + err.status + ')';
      case 'parse': return 'رد غير صالح من السيرفر';
      case 'auth': return 'اسم المستخدم أو كلمة المرور غير صحيحة';
      case 'expired': return 'انتهى الاشتراك';
      case 'banned': return 'الحساب موقوف';
      case 'disabled': return 'الحساب غير مفعّل';
      default: return 'حدث خطأ غير متوقع';
    }
  }

  /* ---------- login ---------- */
  /* the current account only changes when the new one logs in successfully */
  function login(account, cb) {
    var cand = { server: account.server, username: account.username, password: account.password };
    get(api({}, cand), function (err, data) {
      if (err) return cb(err);
      if (!data || !data.user_info) return cb({ code: 'parse' });
      var ui = data.user_info;
      if (String(ui.auth) !== '1') return cb({ code: 'auth' });
      var st = String(ui.status || 'Active').toLowerCase();
      if (st === 'expired') return cb({ code: 'expired' });
      if (st === 'banned') return cb({ code: 'banned' });
      if (st === 'disabled') return cb({ code: 'disabled' });
      acc = cand;
      info = data;
      cache = {}; epgCache = {};
      cb(null, data);
    }, 20000);
  }

  /* checks an account without switching to it: cb(err, data) */
  function probe(account, cb) {
    var cand = { server: account.server, username: account.username, password: account.password };
    get(api({}, cand), function (err, data) {
      if (err) return cb(err);
      if (!data || !data.user_info) return cb({ code: 'parse' });
      var ui = data.user_info;
      if (String(ui.auth) !== '1') return cb({ code: 'auth' });
      var st = String(ui.status || 'Active').toLowerCase();
      if (st === 'expired') return cb({ code: 'expired' }, data);
      if (st === 'banned') return cb({ code: 'banned' }, data);
      if (st === 'disabled') return cb({ code: 'disabled' }, data);
      cb(null, data);
    }, 15000);
  }

  /* ---------- items: unify the 3 content types into one shape ---------- */
  function rating(r) {
    var v = parseFloat(r.rating);
    if (!(v > 0)) v = parseFloat(r.rating_5based) * 2;
    return v > 0 ? Math.round(v * 10) / 10 : null;
  }

  /* release year: the year field, the release date, or a year in the name like "(2025)" / "- 2026" */
  function yearOf(r) {
    var y = parseInt(r.year, 10);
    if (!(y > 1900)) y = parseInt(String(r.releaseDate || r.release_date || '').slice(0, 4), 10);
    if (!(y > 1900)) {
      var m = String(r.name || '').match(/(^|\D)(19|20)\d{2}(?!\d)/g);
      if (m) y = parseInt(m[m.length - 1].replace(/\D/g, ''), 10);
    }
    return y > 1900 && y <= new Date().getFullYear() + 1 ? y : 0;
  }

  /* newest first: by release year, then by the date it was added to the server */
  function newestFirst(list) {
    return list.slice().sort(function (a, b) { return ((b.year || 0) - (a.year || 0)) || ((b.added || 0) - (a.added || 0)); });
  }

  function norm(type, r) {
    if (type === 'live') {
      return { type: 'live', id: r.stream_id, name: r.name || '', icon: r.stream_icon || '',
        num: r.num, cat: r.category_id, archive: r.tv_archive };
    }
    if (type === 'vod') {
      return { type: 'vod', id: r.stream_id, name: r.name || '', icon: r.stream_icon || '',
        num: r.num, cat: r.category_id, ext: r.container_extension || 'mp4', rating: rating(r),
        year: yearOf(r), added: parseInt(r.added, 10) || 0 };
    }
    return { type: 'series', id: r.series_id, name: r.name || '', icon: r.cover || '',
      num: r.num, cat: r.category_id, rating: rating(r),
      year: yearOf(r), added: parseInt(r.last_modified, 10) || 0 };
  }

  var ACT = {
    live: ['get_live_categories', 'get_live_streams'],
    vod: ['get_vod_categories', 'get_vod_streams'],
    series: ['get_series_categories', 'get_series']
  };

  function getCategories(type, cb) {
    var key = 'cats.' + type;
    if (cache[key]) return cb(null, cache[key]);
    get(api({ action: ACT[type][0] }), function (err, data) {
      if (err) return cb(err);
      var list = [];
      if (data && data.length) {
        for (var i = 0; i < data.length; i++) {
          list.push({ id: String(data[i].category_id), name: data[i].category_name || '' });
        }
      }
      cache[key] = list;
      cb(null, list);
    });
  }

  /* categoryId null = everything of that type */
  function getStreams(type, categoryId, cb) {
    var key = 'streams.' + type + '.' + (categoryId === null ? '*' : categoryId);
    if (cache[key]) return cb(null, cache[key]);
    var p = { action: ACT[type][1] };
    if (categoryId !== null) p.category_id = categoryId;
    get(api(p), function (err, data) {
      if (err) return cb(err);
      var list = [];
      if (data && data.length) {
        for (var i = 0; i < data.length; i++) list.push(norm(type, data[i]));
      }
      if (type === 'live') {
        list.sort(function (a, b) { return (parseInt(a.num, 10) || 0) - (parseInt(b.num, 10) || 0); });
      }
      cache[key] = list;
      cb(null, list);
    }, 60000);
  }

  /* Arabic-friendly search normalisation */
  function simplify(s) {
    return String(s || '').toLowerCase()
      .replace(/[ً-ْـ]/g, '')        /* tashkeel + tatweel */
      .replace(/[آأإ]/g, 'ا')   /* آ أ إ -> ا */
      .replace(/ة/g, 'ه')                 /* ة -> ه */
      .replace(/ى/g, 'ي');                /* ى -> ي */
  }

  function search(type, query, cb) {
    var q = simplify(trim(query));
    if (!q) return cb(null, []);
    getStreams(type, null, function (err, all) {
      if (err) return cb(err);
      var out = [];
      for (var i = 0; i < all.length && out.length < 500; i++) {
        if (simplify(all[i].name).indexOf(q) !== -1) out.push(all[i]);
      }
      cb(null, out);
    });
  }

  function getVodInfo(id, cb) {
    var key = 'vodinfo.' + id;
    if (cache[key]) return cb(null, cache[key]);
    get(api({ action: 'get_vod_info', vod_id: id }), function (err, data) {
      if (err) return cb(err);
      cache[key] = data || {};
      cb(null, cache[key]);
    });
  }

  function getSeriesInfo(id, cb) {
    var key = 'seriesinfo.' + id;
    if (cache[key]) return cb(null, cache[key]);
    get(api({ action: 'get_series_info', series_id: id }), function (err, data) {
      if (err) return cb(err);
      data = data || {};
      /* episodes: { "1":[...], "2":[...] } -> sorted seasons array */
      var eps = data.episodes || {};
      var seasons = [];
      for (var s in eps) {
        if (!eps.hasOwnProperty(s)) continue;
        var list = eps[s] || [];
        if (!list.length) continue;
        var arr = [];
        for (var i = 0; i < list.length; i++) {
          var e = list[i], ei = e.info || {};
          arr.push({
            id: e.id, num: parseInt(e.episode_num, 10) || (i + 1), season: s,
            title: e.title || '', ext: e.container_extension || 'mp4',
            image: ei.movie_image || ei.cover_big || '', plot: ei.plot || '',
            duration: ei.duration || '', secs: parseInt(ei.duration_secs, 10) || 0
          });
        }
        arr.sort(function (a, b) { return a.num - b.num; });
        seasons.push({ num: s, episodes: arr });
      }
      seasons.sort(function (a, b) { return (parseInt(a.num, 10) || 0) - (parseInt(b.num, 10) || 0); });
      var out = { info: data.info || {}, seasons: seasons };
      cache[key] = out;
      cb(null, out);
    });
  }

  /* now / next programme for a live channel (cached 3 minutes) */
  function getShortEpg(streamId, cb) {
    var c = epgCache[streamId];
    if (c && U.now() - c.t < 180000) return cb(null, c.list);
    get(api({ action: 'get_short_epg', stream_id: streamId, limit: 4 }), function (err, data) {
      if (err) return cb(err);
      var raw = (data && data.epg_listings) || [];
      var list = [];
      for (var i = 0; i < raw.length; i++) {
        var p = raw[i];
        var st = parseInt(p.start_timestamp, 10) * 1000 || Date.parse(String(p.start).replace(' ', 'T'));
        var en = parseInt(p.stop_timestamp, 10) * 1000 || Date.parse(String(p.end || p.stop).replace(' ', 'T'));
        list.push({ title: U.b64(p.title), desc: U.b64(p.description), start: st, end: en });
      }
      var nowT = U.now();
      list = list.filter(function (x) { return !(x.end && x.end < nowT); });
      list.sort(function (a, b) { return a.start - b.start; });
      epgCache[streamId] = { t: U.now(), list: list };
      cb(null, list);
    }, 15000);
  }

  /* ---------- stream urls ---------- */
  function base(kind) {
    return acc.server + '/' + kind + '/' + encodeURIComponent(acc.username) + '/' + encodeURIComponent(acc.password) + '/';
  }
  function liveUrl(item, fmt) { return base('live') + item.id + '.' + (fmt || 'ts'); }
  function movieUrl(item) { return base('movie') + item.id + '.' + (item.ext || 'mp4'); }
  function episodeUrl(ep) { return base('series') + ep.id + '.' + (ep.ext || 'mp4'); }

  function clearCache() { cache = {}; epgCache = {}; }

  return {
    parseServer: parseServer, login: login, probe: probe, errorText: errorText,
    getCategories: getCategories, getStreams: getStreams, search: search, newestFirst: newestFirst,
    getVodInfo: getVodInfo, getSeriesInfo: getSeriesInfo, getShortEpg: getShortEpg,
    liveUrl: liveUrl, movieUrl: movieUrl, episodeUrl: episodeUrl,
    clearCache: clearCache,
    info: function () { return info; },
    account: function () { return acc; }
  };
})();

/* ==========================================================================
   pair.js — "login from phone" on the TV side.

   1. The TV makes a random channel name + a random 16-byte key.
   2. The QR code holds  <pairPage>#t=<channel>&k=<key>.
      The part after # never leaves the phone, so the relay never sees the key.
   3. The phone page encrypts {server, user, pass} with the key and posts it
      to the relay channel. The TV listens on that channel, checks and decrypts.
   ========================================================================== */
var Pair = (function () {
  var session = null;
  var xhr = null;
  var retryTimer = null;
  var active = false;
  var errors = 0;
  var seen = {};
  var cb = null;

  function enabled() {
    return CONFIG.pairPage && CONFIG.pairPage.indexOf('USERNAME') === -1;
  }

  function randomId(n) {
    var chars = 'abcdefghijklmnopqrstuvwxyz0123456789', out = '';
    var b = PairCrypto.randomBytes(n);
    for (var i = 0; i < n; i++) out += chars.charAt(b[i] % 36);
    return out;
  }

  /* callbacks: {onStatus(state), onCredentials({server, username, password})}
     states: connecting | ready | offline | received                           */
  function start(callbacks) {
    stop();
    if (!enabled()) return null;
    cb = callbacks || {};
    active = true;
    errors = 0;
    seen = {};
    var key = PairCrypto.randomBytes(16);
    session = {
      topic: 'iptvp' + randomId(20),
      key: key,
      since: String(Math.floor(U.now() / 1000) - 10)
    };
    session.url = CONFIG.pairPage + '#t=' + session.topic + '&k=' + PairCrypto.b64urlEncode(key);
    status('connecting');
    connect();
    return session;
  }

  function stop() {
    active = false;
    clearTimeout(retryTimer);
    if (xhr) { try { xhr.abort(); } catch (e) {} xhr = null; }
  }

  function status(s) { if (cb && cb.onStatus) { try { cb.onStatus(s); } catch (e) {} } }

  function connect() {
    if (!active) return;
    var my = new XMLHttpRequest();
    xhr = my;
    var used = 0, buffer = '';
    var url = CONFIG.relay + '/' + session.topic + '/json?since=' + encodeURIComponent(session.since);

    function consume() {
      var txt = my.responseText || '';
      if (txt.length <= used) return;
      buffer += txt.substring(used);
      used = txt.length;
      var nl;
      while ((nl = buffer.indexOf('\n')) !== -1) {
        var line = buffer.substring(0, nl);
        buffer = buffer.substring(nl + 1);
        handleLine(line);
      }
    }

    try {
      my.open('GET', url, true);
      my.onprogress = function () { if (xhr === my) consume(); };
      my.onreadystatechange = function () {
        if (xhr !== my) return;
        if (my.readyState === 3) consume();
        if (my.readyState === 4) {
          consume();
          if (my.status >= 200 && my.status < 300) errors = 0;
          else errors++;
          retry();
        }
      };
      my.send();
    } catch (e) {
      errors++;
      retry();
    }
  }

  function retry() {
    if (!active) return;
    if (errors >= 2) status('offline');
    clearTimeout(retryTimer);
    retryTimer = setTimeout(connect, errors ? Math.min(30000, 3000 * errors) : 1000);
  }

  function handleLine(line) {
    if (!line) return;
    var ev;
    try { ev = JSON.parse(line); } catch (e) { return; }
    if (ev.event === 'open' || ev.event === 'keepalive') {
      errors = 0;
      status('ready');
      return;
    }
    if (ev.event !== 'message' || !ev.message) return;
    if (ev.id) {
      if (seen[ev.id]) return;
      seen[ev.id] = true;
      session.since = ev.id;
    }
    var text = PairCrypto.open(session.key, ev.message);
    if (!text) return;                           /* not ours / tampered: ignore */
    var data;
    try { data = JSON.parse(text); } catch (e) { return; }
    if (!data || !data.s || !data.u || !data.p) return;
    status('received');
    if (cb && cb.onCredentials) cb.onCredentials({ server: data.s, username: data.u, password: data.p });
  }

  return {
    enabled: enabled, start: start, stop: stop,
    current: function () { return session; }
  };
})();

/* ==========================================================================
   player.js — Android (car screen) version.
   Two ways to play, tried one after the other when a stream does not start:
     'web'    : inside the page — hls.js for .m3u8, mpegts.js for .ts,
                the browser's own <video> for files (mp4 ...)
     'native' : Android's own MediaPlayer drawn behind the transparent page
                (like Samsung AVPlay on the TV) — plays mkv / AC3 / HEVC files
                and lets you choose the audio and subtitle tracks.
   Live TV starts with 'web', movies / episodes with 'native' (setting
   'engine' = auto). Settings can force one of them.
   Events sent to opts.on(event, data):
     'buffer' (true/false), 'ready' (durationMs), 'state' ('playing'|'paused'),
     'time' (ms), 'ended', 'error' (text), 'subtitle' ({text, duration})
   ========================================================================== */
var Player = (function () {
  var NP = window.NativePlayer || null;     /* Java side (MainActivity) */
  var video = null;
  var handler = null;
  var state = 'idle';      /* idle | loading | playing | paused | ended | error */
  var duration = 0;
  var current = 0;
  var token = 0;           /* increases on every open/stop -> stale callbacks are ignored */
  var aspect = 'fit';
  var subsOn = false;
  var eng = '';            /* engine in use: 'web' | 'native' */
  var hls = null, ts = null;
  var npTok = 0, npOn = null;
  var job = null;          /* {url, opts, engines, step, started, timer} */
  var START_MS = 15000;    /* an engine that shows nothing for this long counts as failed */
  var webNetFails = 0;     /* the page may not read this server: after 2 such errors start with 'native' */
  var stats = { live: false, t0: 0, startMs: 0, stalls: 0, stallMs: 0, stallAt: 0 };

  /* Picture modes. mode: contain = whole picture, cover = fill and crop, fill = stretch */
  var ASPECTS = {
    fit:   { mode: 'contain', z: 1, name: 'الأبعاد الأصلية',
             desc: 'الصورة كاملة بأبعادها الصحيحة (الأنسب لشاشة السيارة)' },
    cover: { mode: 'cover', z: 1, name: 'ملء الشاشة بدون تمطيط',
             desc: 'تملأ الشاشة كلها وتقص الأطراف الزائدة' },
    zoom:  { mode: 'contain', z: 1.15, name: 'تكبير بسيط',
             desc: 'تكبير 15% يخفي الحواف السوداء الرفيعة' },
    fill:  { mode: 'fill', z: 1, name: 'تمطيط لملء الشاشة',
             desc: 'تملأ الشاشة كلها وقد تتمطط الصورة' }
  };
  var ASPECT_ORDER = ['fit', 'cover', 'zoom', 'fill'];

  var LANGS = {
    ar: 'العربية', ara: 'العربية', en: 'الإنجليزية', eng: 'الإنجليزية',
    fr: 'الفرنسية', fre: 'الفرنسية', fra: 'الفرنسية', tr: 'التركية', tur: 'التركية',
    es: 'الإسبانية', spa: 'الإسبانية', de: 'الألمانية', ger: 'الألمانية', deu: 'الألمانية',
    it: 'الإيطالية', ita: 'الإيطالية', hi: 'الهندية', hin: 'الهندية', ur: 'الأردية', urd: 'الأردية',
    fa: 'الفارسية', per: 'الفارسية', fas: 'الفارسية', ru: 'الروسية', rus: 'الروسية',
    ko: 'الكورية', kor: 'الكورية', ja: 'اليابانية', jpn: 'اليابانية', pt: 'البرتغالية', por: 'البرتغالية'
  };

  var ENGINE_NAMES = { auto: 'تلقائي', web: 'مشغل الويب', native: 'مشغل أندرويد' };

  function init() {
    video = U.$('html5-player');
    /* car screens are wider than films: fill the screen by default (once; the
       viewer can still pick another mode from «أبعاد الشاشة») */
    if (!Store.getSettings().aspectCar) { Store.setSetting('aspect', 'cover'); Store.setSetting('aspectCar', 1); }
    aspect = Store.getSettings().aspect;
    if (!ASPECTS[aspect]) aspect = 'cover';
    /* events from the Java player */
    window.__np = function (evt, data, tk) { if (npOn) npOn(evt, data, parseInt(tk, 10)); };
  }

  function emit(evt, data) { if (handler) { try { handler(evt, data); } catch (e) { /* ignore UI errors */ } } }

  function setNativeLayer(on) {
    U.toggleClass(document.documentElement, 'np-active', on);
  }

  /* which engines to try, in order */
  function engineList(live) {
    var pref = Store.getSettings().engine || 'auto';
    var webOk = true, natOk = !!NP;
    if (pref === 'web' || !natOk) return ['web'];
    if (pref === 'native') return ['native', 'web'];
    if (!webOk) return ['native'];
    if (webNetFails >= 2) return ['native', 'web'];
    return live ? ['web', 'native'] : ['native', 'web'];
  }

  /* ------------------------------------------------------------------ */
  function play(url, opts) {
    stop(true);
    soundFocus(true);
    opts = opts || {};
    token++;
    handler = opts.on || null;
    state = 'loading'; duration = 0; current = 0; subsOn = false;
    stats = { live: !!opts.live, t0: new Date().getTime(), startMs: 0, stalls: 0, stallMs: 0, stallAt: 0 };
    job = { url: url, opts: opts, engines: engineList(!!opts.live), step: -1, started: false, timer: null, why: [] };
    emit('buffer', true);
    nextEngine('');
  }

  /* start the next engine in the list, or give up */
  function nextEngine(reason) {
    if (!job) return;
    if (reason) job.why.push(eng + ':' + reason);
    if (eng === 'web' && /NetworkError|networkError|MEDIA_ERR_2/.test(reason || '')) webNetFails++;
    clearTimeout(job.timer);
    stopEngine(true);
    job.step++;
    if (job.step >= job.engines.length) {
      state = 'error';
      Diag.send('car-fail-' + (job.opts.live ? 'live' : 'vod'), job.why.join(' | ') + ' url=.' + extOf(job.url));
      emit('error', job.why.join(' | ') || 'NO_ENGINE');
      return;
    }
    token++;
    var my = token;
    eng = job.engines[job.step];
    state = 'loading';
    job.timer = setTimeout(function () { if (my === token && job && !job.started) nextEngine('TIMEOUT'); }, START_MS);
    if (eng === 'native') npOpen(job.url, job.opts.startAt || 0, my);
    else webOpen(job.url, job.opts.startAt || 0, my, !!job.opts.live);
  }

  function extOf(url) { var m = /\.([a-z0-9]{2,4})(\?|$)/i.exec(url || ''); return m ? m[1].toLowerCase() : '?'; }

  /* first picture / first moving time: this engine works */
  function started(my) {
    if (my !== token || !job || job.started) return;
    job.started = true;
    clearTimeout(job.timer);
    if (!stats.startMs) stats.startMs = new Date().getTime() - stats.t0;
    Diag.send('car-ok-' + eng + '-' + (job.opts.live ? 'live' : 'vod'), '.' + extOf(job.url) + ' start=' + stats.startMs + 'ms' +
      (job.why.length ? ' after ' + job.why.join(' | ') : ''));
  }

  /* an engine reported an error */
  function failed(my, reason) {
    if (my !== token) return;
    if (job && !job.started) { nextEngine(reason); return; }
    state = 'error';
    emit('error', reason);
  }

  /* ---------------- Android MediaPlayer ---------------- */
  function npOpen(url, startAt, my) {
    setNativeLayer(true);
    applyAspect();
    npTok++;
    var t = npTok, seeking = startAt > 0;
    npOn = function (evt, data, tk) {
      if (tk !== t || my !== token) return;
      switch (evt) {
        case 'prepared':
          duration = parseInt(data, 10) || 0;
          if (startAt > 0) NP.seek(Math.floor(startAt));
          NP.play();
          state = 'playing';
          emit('ready', duration);
          emit('state', 'playing');
          break;
        case 'render':
          started(my);
          emit('buffer', false);
          break;
        case 'buffer':
          if (data === '1') {
            if (stats.startMs) { stats.stalls++; stats.stallAt = new Date().getTime(); }
            emit('buffer', true);
          } else {
            if (stats.stallAt) { stats.stallMs += new Date().getTime() - stats.stallAt; stats.stallAt = 0; }
            emit('buffer', false);
          }
          break;
        case 'time':
          var v = parseInt(data, 10) || 0;
          if (seeking && v < startAt - 5000) break;        /* old position before the jump */
          seeking = false;
          if (v > 0) started(my);
          current = v;
          emit('time', v);
          break;
        case 'seeked':
          seeking = false;
          break;
        case 'sub':
          if (subsOn) emit('subtitle', { text: data, duration: 5000 });
          break;
        case 'ended':
          state = 'ended';
          emit('ended');
          break;
        case 'error':
          failed(my, data);
          break;
      }
    };
    try { NP.open(url, t); } catch (e) { failed(my, 'NATIVE_BRIDGE'); }
  }

  /* ---------------- in-page player (hls.js / mpegts.js / <video>) ---------------- */
  function webOpen(url, startAt, my, live) {
