      if (stats.stallAt) { stats.stallMs += new Date().getTime() - stats.stallAt; stats.stallAt = 0; }
      emit('buffer', false); emit('state', 'playing');
    };
    video.onwaiting = function () {
      if (my !== token) return;
      if (stats.startMs) { stats.stalls++; stats.stallAt = new Date().getTime(); }
      emit('buffer', true);
    };
    video.ontimeupdate = function () {
      if (my !== token) return;
