        failed(my, 'HLS_' + d.type + '_' + d.details);
      });
      hls.on(Hls.Events.SUBTITLE_TRACK_LOADED, function () {});
      hls.loadSource(url);
      hls.attachMedia(video);
    } else if (isTs && window.mpegts && mpegts.getFeatureList().mseLivePlayback) {
      ts = mpegts.createPlayer({ type: 'mpegts', isLive: live, url: url }, {
        enableWorker: false, lazyLoad: false, enableStashBuffer: true, stashInitialSize: 384 * 1024,
        liveBufferLatencyChasing: false, autoCleanupSourceBuffer: true, reuseRedirectedURL: true
