      }
    } catch (e) {}
    return false;
  }

  function subtitlesOff() {
    subsOn = false;
    emit('subtitle', { text: '', duration: 0 });
    try {
      if (eng === 'native') {
        var all = JSON.parse(NP.tracks());
        for (var i = 0; i < all.length; i++) if (all[i].t === 'TEXT' && all[i].s) NP.deselectTrack(all[i].i);
      } else if (hls) { hls.subtitleTrack = -1; hls.subtitleDisplay = false; }
    } catch (e) {}
  }

  /* ---------------- which engine (settings) ---------------- */
  function engineName(k) { return ENGINE_NAMES[k || Store.getSettings().engine || 'auto'] || ENGINE_NAMES.auto; }
  function cycleEngine() {
    var order = NP ? ['auto', 'web', 'native'] : ['auto', 'web'];
    var cur = Store.getSettings().engine || 'auto', i = 0;
    for (var k = 0; k < order.length; k++) if (order[k] === cur) i = k;
