    },
    aspectZoom: function (k) { return (ASPECTS[k || aspect] || ASPECTS.fit).z; },
    aspectName: function () { return (ASPECTS[aspect] || ASPECTS.fit).name; },
    getTracks: getTracks, selectTrack: selectTrack, subtitlesOff: subtitlesOff,
    subtitlesOn: function () { return subsOn; },
    state: function () { return state; },
