/* ==========================================================================
   vlist.js — a fast "windowed" list / grid for the remote control.
   Only the visible rows are in the page, so categories with thousands of
   channels stay smooth on the TV.

   new VList(element, {
     cols: 1,              columns per row (1 = list)
     rows: 8,              fully visible rows
     extra: 1,             extra (partly visible) rows to render below
     rowClass: 'vrow',
     render: function(item, index) { return '<div ...>' }   html of one cell
     onFocus: function(index, item) {}
   })
   Column 0 is drawn on the RIGHT because the page is right-to-left,
   so the "next" item in a row is to the left.
   ========================================================================== */
function VList(el, opts) {
  this.el = el;
  this.cols = opts.cols || 1;
  this.rows = opts.rows || 8;
  this.extra = opts.extra === undefined ? 1 : opts.extra;
  this.rowClass = opts.rowClass || 'vrow';
  this.render = opts.render;
  this.onFocus = opts.onFocus || null;
  this.items = [];
  this.index = 0;
  this.top = 0;
  this.drawnTop = -1;
  this.active = false;
  el.__vlist = this;
  U.addClass(el, 'vlist');
}

VList.prototype.setItems = function (items, index) {
  this.items = items || [];
  this.index = U.clamp(index || 0, 0, Math.max(0, this.items.length - 1));
  this.top = 0;
  this.drawnTop = -1;
  this.scroll();
  this.draw();
  this.fireFocus();
};

VList.prototype.totalRows = function () { return Math.ceil(this.items.length / this.cols); };

VList.prototype.scroll = function () {
  var row = Math.floor(this.index / this.cols);
  var margin = this.rows > 4 ? 1 : 0;
  if (row < this.top + margin) this.top = row - margin;
  if (row > this.top + this.rows - 1 - margin) this.top = row - this.rows + 1 + margin;
  var maxTop = Math.max(0, this.totalRows() - this.rows);
  this.top = U.clamp(this.top, 0, maxTop);
};

VList.prototype.draw = function () {
  var html = '';
  var first = this.top * this.cols;
  var last = Math.min(this.items.length, (this.top + this.rows + this.extra) * this.cols);
  for (var i = first; i < last; i += this.cols) {
    html += '<div class="' + this.rowClass + '">';
    for (var j = i; j < Math.min(i + this.cols, last); j++) {
      html += this.render(this.items[j], j);
    }
    html += '</div>';
  }
  this.el.innerHTML = html;
  this.drawnTop = this.top;
  this.markFocus();
};

VList.prototype.markFocus = function () {
  var old = this.el.querySelectorAll('.focused');
  for (var i = 0; i < old.length; i++) U.removeClass(old[i], 'focused');
  var cur = this.el.querySelector('[data-i="' + this.index + '"]');
  if (cur) U.addClass(cur, 'focused');
  U.toggleClass(this.el, 'active', this.active);
};

VList.prototype.setActive = function (on) {
  this.active = on;
  U.toggleClass(this.el, 'active', on);
};

VList.prototype.focusTo = function (i) {
  if (!this.items.length) return false;
  i = U.clamp(i, 0, this.items.length - 1);
  if (i === this.index) return false;
  this.index = i;
  this.scroll();
  if (this.top !== this.drawnTop) this.draw();
  else this.markFocus();
  this.fireFocus();
  return true;
};

VList.prototype.fireFocus = function () {
  if (this.onFocus && this.items.length) this.onFocus(this.index, this.items[this.index]);
};

/* dir: 'up' | 'down' | 'next' | 'prev'. Returns false at an edge. */
VList.prototype.move = function (dir) {
  var n = this.items.length, c = this.cols, i = this.index;
  if (!n) return false;
  if (dir === 'next') { if (c === 1 || (i % c) === c - 1 || i + 1 >= n) return false; return this.focusTo(i + 1); }
  if (dir === 'prev') { if (c === 1 || (i % c) === 0) return false; return this.focusTo(i - 1); }
  if (dir === 'up') { if (i - c < 0) return false; return this.focusTo(i - c); }
  if (dir === 'down') {
    if (i + c < n) return this.focusTo(i + c);
    if (Math.floor(i / c) < this.totalRows() - 1) return this.focusTo(n - 1);
    return false;
  }
  return false;
};

VList.prototype.page = function (dir) {
  var step = this.rows * this.cols;
  return this.focusTo(this.index + (dir > 0 ? step : -step));
};

VList.prototype.current = function () { return this.items[this.index]; };

/* touch screen: move the visible rows with the finger, the focus stays where it is */
VList.prototype.scrollTo = function (top) {
  var maxTop = Math.max(0, this.totalRows() - this.rows);
  top = U.clamp(Math.round(top), 0, maxTop);
  if (top === this.top) return false;
  this.top = top;
  this.draw();
  return true;
};

/* redraw the current window (after a favourite changed etc.) */
VList.prototype.refresh = function () { this.draw(); };

/* move by remote keys; RTL aware (left = next column) */
VList.prototype.key = function (k) {
  if (k === 'up') return this.move('up');
  if (k === 'down') return this.move('down');
  if (k === 'left') return this.move('next');
  if (k === 'right') return this.move('prev');
  if (k === 'chup') return this.page(-1);
  if (k === 'chdown') return this.page(1);
  return false;
};

/* ==========================================================================
   ui.js — toast messages, loading spinner, dialogs, option menus and clock
   ========================================================================== */

/* every screen file adds itself here: Screens.home = {...} */
var Screens = {};

var UI = (function () {
  var toastTimer = null;
  var modal = null;        /* the open dialog/menu (gets the remote keys first) */

  function toast(msg, ms) {
    var t = U.$('toast');
    t.innerHTML = U.esc(msg);
    U.addClass(t, 'show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { U.removeClass(t, 'show'); }, ms || 2600);
  }

  function loading(on, text) {
    U.$('loader-txt').innerHTML = U.esc(text || '');
    U.toggleClass(U.$('loader'), 'show', !!on);
  }

  function close() {
    modal = null;
    var m = U.$('modal');
    m.innerHTML = '';
    m.className = '';
  }

  /* ---- dialog with buttons in one row ----
     opts: { title, text, buttons:[{label, value}], index, onSelect(value|null) } */
  function confirm(opts) {
    var idx = opts.index || 0;
    var m = U.$('modal');
    function draw() {
      var h = '<div class="mdl-box"><h2>' + U.esc(opts.title || '') + '</h2>';
      if (opts.text) h += '<p>' + U.esc(opts.text) + '</p>';
      h += '<div class="btn-row center">';
      for (var i = 0; i < opts.buttons.length; i++) {
        h += '<div class="btn' + (i === idx ? ' focused' : '') + (opts.buttons[i].danger ? ' danger' : '') + '">' +
          U.esc(opts.buttons[i].label) + '</div>';
      }
      m.innerHTML = h + '</div></div>';
    }
    draw();
    U.addClass(m, 'show');
    modal = {
      onKey: function (k) {
        if (k === 'left' && idx < opts.buttons.length - 1) { idx++; draw(); }
        else if (k === 'right' && idx > 0) { idx--; draw(); }
        else if (k === 'enter') { var v = opts.buttons[idx].value; close(); if (opts.onSelect) opts.onSelect(v); }
        else if (k === 'back') { close(); if (opts.onSelect) opts.onSelect(null); }
      }
    };
  }

  /* ---- vertical option list ----
     opts: { title, items:[{label, sub, value, selected}], onSelect(value|null),
             onFocus(value)  called while moving (live preview),
             side: true      panel on the right, video stays visible }      */
  function menu(opts) {
    var m = U.$('modal');
    var start = 0, two = false;
    for (var i = 0; i < opts.items.length; i++) {
      if (opts.items[i].selected) start = i;
      if (opts.items[i].sub) two = true;
    }
    m.className = opts.side ? 'side' : '';
    m.innerHTML = '<div class="mdl-box menu"><h2>' + U.esc(opts.title || '') + '</h2><div id="mdl-list"></div>' +
      (opts.hint ? '<div class="mdl-hint">' + U.esc(opts.hint) + '</div>' : '') + '</div>';
    U.addClass(m, 'show');
    var list = new VList(U.$('mdl-list'), {
      rows: two ? 5 : 7, extra: 0, rowClass: 'mrow',
      render: function (it, idx) {
        return '<div class="mitem' + (two ? ' two' : '') + (it.selected ? ' sel' : '') + '" data-i="' + idx + '">' +
          '<span class="mcheck"></span><span class="mtxt"><b>' + U.esc(it.label) + '</b>' +
          (it.sub ? '<small>' + U.esc(it.sub) + '</small>' : '') + '</span></div>';
      },
      onFocus: function (idx, it) { if (opts.onFocus && it) opts.onFocus(it.value); }
    });
    list.setActive(true);
    list.setItems(opts.items, start);
    modal = {
      onKey: function (k) {
        if (k === 'up' || k === 'down') list.key(k);
        else if (k === 'enter') { var v = list.current().value; close(); if (opts.onSelect) opts.onSelect(v); }
        else if (k === 'back' || (opts.closeKey && k === opts.closeKey)) { close(); if (opts.onSelect) opts.onSelect(null); }
      }
    };
  }

  /* ---- clock in every header ---- */
  function clockText() {
    var d = SaudiTime.now();
    SaudiTime.use24 = !!Store.getSettings().clock24;
    return SaudiTime.fmt(d.getUTCHours(), d.getUTCMinutes());
  }
  function tickClock() {
    var txt = clockText();
    var els = document.querySelectorAll('.clock');
    for (var i = 0; i < els.length; i++) els[i].innerHTML = txt;
  }
  function startClock() { tickClock(); setInterval(tickClock, 15000); }

  return {
    toast: toast, loading: loading, confirm: confirm, menu: menu, close: close,
    startClock: startClock, tickClock: tickClock, clockText: clockText,
    modal: function () { return modal; }
  };
})();

