    try { inp.setSelectionRange(inp.value.length, inp.value.length); } catch (e) {}
  },

  /* after typing the server: if it was a full M3U link, take user/pass from it */
  afterServer: function () {
    var ins = this.inputs();
    var p = Xtream.parseServer(ins[0].value);
    if (p.username) {
      ins[0].value = p.server;
      ins[1].value = p.username;
      ins[2].value = p.password || '';
      UI.toast('تم استخراج بيانات الدخول من الرابط');
      return true;
    }
    return false;
  },

  onKey: function (k) {
    var ins = this.inputs();
    if (this.busy) return;
    switch (k) {
      case 'up': if (this.f > 0) { this.f--; this.draw(); } break;
      case 'down': if (this.f < 3) { this.f++; this.draw(); } break;
      case 'enter':
        if (this.f < 3) this.edit(); else this.submit();
        break;
      case 'imedone':
        if (this.f < 3) ins[this.f].blur();
        if (this.f === 0 && this.afterServer()) this.f = 3;
        else if (this.f < 3) this.f++;
        this.draw();
        break;
      case 'imecancel':
        if (this.f < 3) ins[this.f].blur();
        this.draw();
        break;
      case 'imeup':
        if (this.f < 3) ins[this.f].blur();
        if (this.f > 0) this.f--;
        this.draw();
        break;
      case 'back':
        if (this.params.fromSettings || this.params.add) App.back();
        else App.exitConfirm();
        break;
    }
  },

  /* from the playlists screen: check the new playlist and keep it (the one in use stays) */
  addPlaylist: function (acc) {
    var self = this;
    UI.loading(true, 'جاري التحقق من قائمة التشغيل...');
    Xtream.probe(acc, function (err) {
      self.busy = false;
      UI.loading(false);
      if (err && err.code === 'auth') {
        self.msg(Xtream.errorText(err));
        if (Pair.enabled()) self.pairStatus('ready');
        return;
      }
      var pl = Store.savePlaylist(acc);
      Pair.stop();
      UI.toast(err ? 'تمت إضافة القائمة لكنها لا تعمل حالياً' : 'تمت إضافة قائمة التشغيل ✓');
      App.back({ added: pl.id });
    });
  },

  submit: function () {
    var self = this;
    var ins = this.inputs();
    this.afterServer();
    var p = Xtream.parseServer(ins[0].value);
    var acc = {
      server: p.server,
      username: String(ins[1].value).replace(/^\s+|\s+$/g, ''),
      password: String(ins[2].value).replace(/^\s+|\s+$/g, '')
    };
    if (!acc.server) { this.msg('اكتب رابط السيرفر'); this.f = 0; this.draw(); return; }
    if (!acc.username) { this.msg('اكتب اسم المستخدم'); this.f = 1; this.draw(); return; }
    if (!acc.password) { this.msg('اكتب كلمة المرور'); this.f = 2; this.draw(); return; }
    this.msg('');
    this.busy = true;
    if (this.params.add) { this.addPlaylist(acc); return; }
    UI.loading(true, 'جاري تسجيل الدخول...');
    Xtream.login(acc, function (err) {
      self.busy = false;
      UI.loading(false);
      if (err) {
        self.msg(Xtream.errorText(err));
        /* a failed attempt keeps the phone channel open for another try */
        if (Pair.enabled()) self.pairStatus('ready');
        return;
      }
      Store.setAccount(acc);
      Pair.stop();
      Xtream.clearCache();
      App.go('home', {}, { reset: true });
    });
  }
};

