  };

  S.nextNews = function () {
    if (this.news.length < 2) return;
    this.newsIdx = (this.newsIdx + 1) % this.news.length;
    this.showNews(true);
  };

  /* ---------------- focus + keys ---------------- */
  S.focus = function () {
    var els = this.el.querySelectorAll('[data-z]');
    for (var i = 0; i < els.length; i++) {
      var on = els[i].getAttribute('data-z') === this.zone && parseInt(els[i].getAttribute('data-i'), 10) === this.idx[this.zone];
      U.toggleClass(els[i], 'focused', on);
    }
  };

  S.move = function (d) {
    var z = this.zone, n = z === 'top' ? TOP.length : NAV.length, i = this.idx[z] + d;
    if (i < 0 || i >= n) return;
    this.idx[z] = i;
    this.focus();
  };

  S.onKey = function (k) {
    if (k === 'left') this.move(1);
    else if (k === 'right') this.move(-1);
    else if (k === 'up' && this.zone === 'nav') { this.zone = 'top'; this.focus(); }
    else if (k === 'down' && this.zone === 'top') { this.zone = 'nav'; this.focus(); }
    else if (k === 'enter') this.open();
    else if (k === 'back') { if (this.zone !== 'nav') { this.zone = 'nav'; this.focus(); } else App.exitConfirm(); }
  };

  S.open = function () {
    var i = this.idx[this.zone];
    if (this.zone === 'top') {
      if (TOP[i].id === 'settings') App.go('settings', {});
      else this.searchMenu();
    } else {
