  /* ---------------- rendering ---------------- */
  S.renderCat = function (c, i) {
    var cur = this.curCat && this.curCat.id === c.id ? ' cur' : '';
    return '<div class="sitem' + cur + '" data-i="' + i + '">' +
      '<span class="sico">' + ICONS[c.icon || 'folder'] + '</span>' +
      '<span class="sname">' + U.esc(c.name) + '</span></div>';
  };

  S.renderChannel = function (it, i) {
    return '<div class="litem" data-i="' + i + '">' +
      '<span class="lnum">' + U.esc(it.num || (i + 1)) + '</span>' +
      U.img(it.icon, it.name, 'llogo') +
      '<span class="lname">' + U.esc(it.name) + '</span>' +
      (this.favSet[it.id] ? '<span class="lfav">' + ICONS.star + '</span>' : '') +
      '</div>';
  };

  S.renderPoster = function (it, i) {
    var badge = it.rating ? '<span class="rate">' + ICONS.star + it.rating + '</span>' : '';
    var fav = this.favSet[it.id] ? '<span class="cfav">' + ICONS.star + '</span>' : '';
    var prog = '';
    if (it.type === 'vod') {
      var h = Store.getHist('m:' + it.id);
      if (h && h.dur && !h.done && h.pos > 30000) {
        prog = '<span class="cprog"><i style="width:' + Math.round(h.pos / h.dur * 100) + '%"></i></span>';
      }
    }
    return '<div class="card" data-i="' + i + '">' +
      '<div class="poster">' + U.img(it.icon, it.name, 'pimg') + badge + fav + prog + '</div>' +
      '<div class="ctitle">' + U.esc(it.name) + '</div></div>';
  };

  S.buildFavSet = function () {
    var f = Store.getFavs(this.type);
    this.favSet = {};
    for (var i = 0; i < f.length; i++) this.favSet[f[i].id] = true;
  };

  S.setState = function (kind, text) {
    var el = U.$('br-state');
    if (!kind) { el.style.display = 'none'; el.innerHTML = ''; return; }
    el.style.display = 'block';
    if (kind === 'loading') el.innerHTML = '<div class="spinner"></div>';
    else el.innerHTML = '<div class="state-msg' + (kind === 'error' ? ' err' : '') + '">' + U.esc(text || '') + '</div>';
  };

  S.updateCount = function () {
    var n = this.items.length;
    U.$('br-count').innerHTML = n ? (this.list.index + 1) + ' / ' + n : '';
  };

  S.setZone = function (z) {
    this.zone = z;
    this.side.setActive(z === 'side');
    this.list.setActive(z === 'content');
    U.toggleClass(U.$('br-search-wrap'), 'active', z === 'search');
  };

  /* ---------------- categories ---------------- */
  S.onSideFocus = function () {
    var self = this;
    clearTimeout(this.catTimer);
    var c = this.side.current();
    if (!c || c.id === '__search' || (this.curCat && c.id === this.curCat.id)) return;
    this.catTimer = setTimeout(function () { self.selectCat(self.side.index, false); }, 550);
  };

  S.selectCat = function (i, enterAfter) {
    var self = this;
    var cat = this.cats[i];
    if (!cat) return;
    clearTimeout(this.catTimer);
    this.searching = false;
    this.curCat = cat;
    this.side.refresh();
    U.$('br-cat').innerHTML = U.esc(cat.name);

    if (cat.id === '__search') {
      this.showItems(this.searchResults, EMPTY.__search);
      return;
    }
    if (cat.id === '__fav') { this.showItems(Store.getFavs(this.type), EMPTY.__fav, enterAfter); return; }
    if (cat.id === '__cont') { this.showItems(Store.continueList(this.type), EMPTY.__cont, enterAfter); return; }

    var my = ++this.reqId;
    this.items = [];
    this.list.setItems([]);
    this.updateCount();
    U.$('br-info').innerHTML = '';
    this.setState('loading');
    Xtream.getStreams(this.type, cat.id === '__all' ? null : cat.id, function (err, items) {
      if (my !== self.reqId) return;
      if (err) { self.setState('error', Xtream.errorText(err) + ' — اضغط OK لإعادة المحاولة'); return; }
      /* films and series: newest first (2026, 2025 ...) unless the server's own order is chosen */
      if (self.type !== 'live' && Store.getSettings().sort !== 'server') items = Xtream.newestFirst(items);
      self.showItems(items, EMPTY.other, enterAfter);
    });
  };

  S.showItems = function (items, emptyText, enterAfter) {
    this.items = items || [];
    this.list.setItems(this.items, 0);
    this.setState(this.items.length ? '' : 'empty', emptyText);
    this.updateCount();
    if (!this.items.length) U.$('br-info').innerHTML = '';
    if (enterAfter && this.items.length) this.setZone('content');
  };

  /* ---------------- search ---------------- */
  S.bindSearch = function () {
    if (this.bound) return;
    this.bound = true;
    var self = this;
    var run = U.debounce(function () { self.runSearch(U.$('br-search').value); }, 600);
    this.runLater = run;
    U.$('br-search').addEventListener('input', run);
  };

  S.openSearch = function () {
    var i;
    for (i = 0; i < this.cats.length; i++) if (this.cats[i].id === '__search') break;
    this.side.focusTo(i);
    if (!this.curCat || this.curCat.id !== '__search') this.selectCat(i, false);
    this.setZone('search');
    var inp = U.$('br-search');
    inp.focus();
  };

  S.runSearch = function (q) {
    var self = this;
    q = String(q || '').replace(/^\s+|\s+$/g, '');
    if (q === this.query) return;
    this.query = q;
    if (!this.curCat || this.curCat.id !== '__search') return;
    if (!q) { this.searchResults = []; this.showItems([], EMPTY.__search); return; }
    var my = ++this.reqId;
    this.setState('loading');
    this.searching = true;
    Xtream.search(this.type, q, function (err, res) {
      if (my !== self.reqId) return;
      self.searching = false;
      if (err) { self.setState('error', Xtream.errorText(err)); return; }
      self.searchResults = res;
      self.showItems(res, 'لا توجد نتائج لـ «' + q + '»', self.goResults && self.zone !== 'search');
      self.goResults = false;
    });
  };

  S.closeSearch = function (toResults) {
    var inp = U.$('br-search');
    inp.blur();
    this.runLater.cancel();
    this.goResults = !!toResults;
    this.setZone('side');
    this.runSearch(inp.value);   /* async: moves to the results when they arrive */
    if (toResults && !this.searching && this.items.length && this.curCat && this.curCat.id === '__search') {
      this.goResults = false;
      this.setZone('content');
    }
  };

  /* ---------------- items ---------------- */
  S.onItemFocus = function (i, it) {
    this.updateCount();
    if (this.type !== 'live' || !it) return;
    var self = this;
    this.renderInfo(it, null);
    clearTimeout(this.epgTimer);
    this.epgTimer = setTimeout(function () {
      Xtream.getShortEpg(it.id, function (err, list) {
        var cur = self.list.current();
        if (!cur || cur.id !== it.id) return;
        self.renderInfo(it, err ? [] : list);
      });
    }, 500);
  };

  /* channel details + now/next on the left (live only) */
  S.renderInfo = function (it, epg) {
    var h = '<div class="inf-logo">' + U.img(it.icon, it.name, 'ilogo') + '</div>';
    h += '<div class="inf-name">' + U.esc(it.name) + '</div>';
    h += '<div class="inf-sub">' + (it.num ? 'قناة رقم ' + U.esc(it.num) : '') + '</div>';
    if (epg === null) {
      h += '<div class="inf-epg muted">جاري تحميل دليل البرامج...</div>';
    } else if (!epg.length) {
      h += '<div class="inf-epg muted">لا يوجد دليل برامج لهذه القناة</div>';
    } else {
      h += epgBlock(epg[0], true);
      if (epg[1]) h += epgBlock(epg[1], false);
    }
    U.$('br-info').innerHTML = h;
  };

  function epgBlock(p, isNow) {
    var t = U.fmtClock(new Date(p.start)) + ' - ' + U.fmtClock(new Date(p.end));
    var pct = isNow && p.end > p.start ? U.clamp((U.now() - p.start) / (p.end - p.start), 0, 1) : 0;
    var h = '<div class="inf-epg">';
    h += '<div class="epg-row"><span class="chip' + (isNow ? ' now' : '') + '">' + (isNow ? 'الآن' : 'التالي') + '</span>' +
      '<span class="epg-time">' + t + '</span></div>';
    h += '<div class="epg-title">' + U.esc(p.title) + '</div>';
    if (isNow) h += '<div class="bar" dir="ltr"><i style="width:' + Math.round(pct * 100) + '%"></i></div>';
    if (isNow && p.desc) h += '<div class="epg-desc">' + U.esc(p.desc) + '</div>';
    return h + '</div>';
  }

  S.open = function () {
    var it = this.list.current();
    if (!it) return;
    if (this.type === 'live') App.go('player', { kind: 'live', list: this.items, index: this.list.index, catName: this.curCat ? this.curCat.name : '' });
    else if (this.type === 'vod') App.go('movie', { item: it });
    else App.go('series', { item: it });
  };

  S.toggleFav = function () {
    var it = this.list.current();
    if (!it) return;
    var on = Store.toggleFav(it);
    this.buildFavSet();
    UI.toast(on ? 'تمت الإضافة إلى المفضلة' : 'تمت الإزالة من المفضلة');
    if (this.curCat && this.curCat.id === '__fav') {
      var keep = this.list.index;
      this.items = Store.getFavs(this.type);
      this.list.setItems(this.items, keep);
      this.setState(this.items.length ? '' : 'empty', EMPTY.__fav);
      if (!this.items.length) this.setZone('side');
      this.updateCount();
    } else {
      this.list.refresh();
    }
  };

  /* ---------------- keys ---------------- */
  S.onKey = function (k) {
    if (this.zone === 'search') {
      if (k === 'imedone') this.closeSearch(true);
      else if (k === 'imecancel' || k === 'imeup' || k === 'back') this.closeSearch(false);
      return;
    }

    if (this.zone === 'side') {
      var c = this.side.current();
      switch (k) {
        case 'up': case 'down': case 'chup': case 'chdown':
          this.side.key(k); break;
        case 'enter': case 'left':
          if (!c) break;
          if (this.catsFailed && k === 'enter') { this.show(this.params); break; }
          if (c.id === '__search') { this.openSearch(); break; }
          if (!this.curCat || c.id !== this.curCat.id || (k === 'enter' && !this.items.length)) this.selectCat(this.side.index, true);
          else if (this.items.length) this.setZone('content');
          break;
        case 'back':
          App.back(); break;
      }
      return;
    }

    /* content */
    switch (k) {
      case 'right':
        if (this.type === 'live' || this.list.index % this.list.cols === 0) this.setZone('side');
        else this.list.key(k);
        break;
      case 'left': case 'up': case 'down': case 'chup': case 'chdown':
        this.list.key(k); break;
      case 'enter': case 'play': case 'playpause':
        this.open(); break;
      case 'red':
        this.toggleFav(); break;
      case 'back':
        this.setZone('side'); break;
    }
  };
})();

/* ==========================================================================
   Movie details — poster, story, cast, Play / Resume / Favourite
   ========================================================================== */
Screens.movie = {
  item: null,
  info: {},
  btn: 0,
  btns: [],
  req: 0,

  show: function (params) {
    var self = this;
    var it = this.item = params.item;
    this.info = {};
    this.btn = 0;
    U.$('mv-title').innerHTML = U.esc(it.name);
    U.$('mv-poster').innerHTML = U.img(it.icon, it.name, 'pimg');
    U.setBg(U.$('mv-bg'), it.icon);
    U.$('mv-meta').innerHTML = it.rating ? this.chip('★ ' + it.rating) : '';
    U.$('mv-plot').innerHTML = '<span class="muted">جاري تحميل التفاصيل...</span>';
    U.$('mv-credits').innerHTML = '';
    this.renderButtons();

    var my = ++this.req;
    Xtream.getVodInfo(it.id, function (err, data) {
      if (my !== self.req) return;
      if (err) { U.$('mv-plot').innerHTML = '<span class="muted">' + U.esc(Xtream.errorText(err)) + '</span>'; return; }
      var info = self.info = (data && data.info) || {};
      var md = (data && data.movie_data) || {};
      if (md.container_extension) it.ext = md.container_extension;
      self.renderInfo(info);
    });
  },

  resume: function () { this.renderButtons(); },

  chip: function (t) { return '<span class="chip">' + U.esc(t) + '</span>'; },

  renderInfo: function (info) {
    var it = this.item;
    var bd = info.backdrop_path;
    if (bd && bd.length && typeof bd !== 'string') bd = bd[0];
    U.setBg(U.$('mv-bg'), bd || info.movie_image || it.icon);
    if (info.movie_image && !it.icon) U.$('mv-poster').innerHTML = U.img(info.movie_image, it.name, 'pimg');

    var meta = '';
    var year = String(info.releasedate || info.release_date || '').substr(0, 4);
    if (year && year !== '0000') meta += this.chip(year);
    if (info.duration) meta += this.chip(String(info.duration).replace(/^00:/, ''));
    var r = parseFloat(info.rating) || it.rating;
    if (r) meta += this.chip('★ ' + (Math.round(r * 10) / 10));
    if (info.genre) meta += this.chip(info.genre);
    if (info.country) meta += this.chip(info.country);
    U.$('mv-meta').innerHTML = meta;

    U.$('mv-plot').innerHTML = U.esc(info.plot || info.description || 'لا يوجد وصف لهذا الفيلم.');
    var cr = '';
    if (info.director) cr += '<div><span>إخراج:</span> ' + U.esc(info.director) + '</div>';
    if (info.cast || info.actors) cr += '<div><span>بطولة:</span> ' + U.esc(String(info.cast || info.actors).substr(0, 160)) + '</div>';
    U.$('mv-credits').innerHTML = cr;
  },

  renderButtons: function () {
    var it = this.item;
    var h = Store.getHist('m:' + it.id);
    var b = [];
    if (h && !h.done && h.pos > 30000) {
      b.push({ id: 'resume', label: '▶  استكمال من ' + U.fmtTime(h.pos) });
      b.push({ id: 'start', label: 'من البداية' });
    } else {
      b.push({ id: 'start', label: '▶  تشغيل' });
    }
    b.push({ id: 'fav', label: Store.isFav('vod', it.id) ? '★  في المفضلة' : '☆  أضف للمفضلة' });
    this.btns = b;
    if (this.btn >= b.length) this.btn = 0;
    var html = '';
    for (var i = 0; i < b.length; i++) {
      html += '<div class="btn' + (i === this.btn ? ' focused' : '') + (i === 0 ? ' primary' : '') + '">' + U.esc(b[i].label) + '</div>';
    }
    U.$('mv-btns').innerHTML = html;
  },

  action: function (id) {
    var it = this.item;
    if (id === 'resume') {
      var h = Store.getHist('m:' + it.id);
      App.go('player', { kind: 'movie', item: it, startAt: h ? h.pos : 0 });
    } else if (id === 'start') {
      App.go('player', { kind: 'movie', item: it, startAt: 0 });
    } else if (id === 'fav') {
      var on = Store.toggleFav(it);
      UI.toast(on ? 'تمت الإضافة إلى المفضلة' : 'تمت الإزالة من المفضلة');
      this.renderButtons();
    }
  },

  onKey: function (k) {
    if (k === 'left' && this.btn < this.btns.length - 1) { this.btn++; this.renderButtons(); }
    else if (k === 'right' && this.btn > 0) { this.btn--; this.renderButtons(); }
    else if (k === 'enter') this.action(this.btns[this.btn].id);
    else if (k === 'play' || k === 'playpause') this.action(this.btns[0].id);
    else if (k === 'red') this.action('fav');
    else if (k === 'back') App.back();
  }
};

/* ==========================================================================
   Series details — seasons tabs + episodes list
   Zones (top to bottom): buttons -> seasons -> episodes
   ========================================================================== */
Screens.series = {
  item: null,
  data: null,
  zone: 'btns',
  btn: 0,
  btns: [],
  season: 0,
  req: 0,

  show: function (params) {
    var self = this;
    var it = this.item = params.item;
    this.data = null;
    this.zone = 'btns';
    this.btn = 0;
    this.season = 0;
    U.$('sr-title').innerHTML = U.esc(it.name);
    U.$('sr-poster').innerHTML = U.img(it.icon, it.name, 'pimg');
    U.setBg(U.$('sr-bg'), it.icon);
    U.$('sr-meta').innerHTML = '';
    U.$('sr-plot').innerHTML = '<span class="muted">جاري تحميل الحلقات...</span>';
    U.$('sr-seasons').innerHTML = '';
    U.$('sr-btns').innerHTML = '';

    /* car screen: a tall list of episodes beside the details, easy to scroll with a finger */
    var car = !!(window.ANDROID_APP && !window.IS_TV);
    U.toggleClass(U.$('scr-series'), 'car', car);
    this.eps = new VList(U.$('sr-episodes'), {
      rows: car ? 7 : 3, extra: car ? 2 : 1, rowClass: 'erow',
      render: function (ep, i) { return self.renderEpisode(ep, i); }
    });
    this.eps.setItems([]);

    var my = ++this.req;
    Xtream.getSeriesInfo(it.id, function (err, data) {
      if (my !== self.req) return;
      if (err) { U.$('sr-plot').innerHTML = '<span class="muted">' + U.esc(Xtream.errorText(err)) + '</span>'; return; }
      self.data = data;
      self.renderInfo(data.info || {});
      if (!data.seasons.length) {
        U.$('sr-plot').innerHTML += '<br><span class="muted">لا توجد حلقات متاحة.</span>';
        return;
      }
      /* open on the season of the last watched episode */
      var last = Store.getHist('s:' + it.id);
      var startEp = 0;
      if (last) {
        var pos = self.findEpisode(last.episodeId);
        if (pos) { self.season = pos.s; startEp = pos.e; }
      }
      self.renderSeasons();
      self.eps.setItems(data.seasons[self.season].episodes, startEp);
      self.renderButtons();
      self.setZone('btns');
      /* opened from "continue watching" on the home screen: resume right away */
      if (params.autoplay && last) {
        var at = self.findEpisode(last.episodeId);
        var eh = Store.getHist('e:' + last.episodeId);
        if (at && eh && eh.done) {               /* finished: go on with the next episode */
          var ss = data.seasons;
          if (at.e + 1 < ss[at.s].episodes.length) at = { s: at.s, e: at.e + 1 };
          else if (at.s + 1 < ss.length && ss[at.s + 1].episodes.length) at = { s: at.s + 1, e: 0 };
        }
        if (at) self.play(at.s, at.e, false);
      }
    });
  },

  resume: function (result) {
    if (!this.data) return;
    if (result && result.seasonIdx !== undefined) {
      this.season = result.seasonIdx;
      this.renderSeasons();
      this.eps.setItems(this.data.seasons[this.season].episodes, result.epIdx);
    } else {
      this.eps.refresh();
    }
    this.renderButtons();
    this.setZone(this.zone);
  },

  findEpisode: function (id) {
    var ss = this.data.seasons;
    for (var s = 0; s < ss.length; s++) {
      for (var e = 0; e < ss[s].episodes.length; e++) {
        if (String(ss[s].episodes[e].id) === String(id)) return { s: s, e: e };
      }
    }
    return null;
  },

  renderInfo: function (info) {
    var it = this.item;
    var bd = info.backdrop_path;
    if (bd && bd.length && typeof bd !== 'string') bd = bd[0];
    U.setBg(U.$('sr-bg'), bd || info.cover || it.icon);
    var meta = '';
    var year = String(info.releaseDate || info.releasedate || '').substr(0, 4);
    if (year && year !== '0000') meta += '<span class="chip">' + U.esc(year) + '</span>';
    meta += '<span class="chip">' + this.data.seasons.length + ' مواسم</span>';
    var r = parseFloat(info.rating) || it.rating;
    if (r) meta += '<span class="chip">★ ' + (Math.round(r * 10) / 10) + '</span>';
    if (info.genre) meta += '<span class="chip">' + U.esc(info.genre) + '</span>';
    U.$('sr-meta').innerHTML = meta;
    U.$('sr-plot').innerHTML = U.esc(info.plot || 'لا يوجد وصف لهذا المسلسل.');
  },

  renderButtons: function () {
    var it = this.item;
    var b = [];
    var last = Store.getHist('s:' + it.id);
    var pos = last && this.data ? this.findEpisode(last.episodeId) : null;
    if (pos) {
      var ss = this.data.seasons[pos.s];
      b.push({ id: 'continue', label: '▶  متابعة: الموسم ' + ss.num + ' · الحلقة ' + ss.episodes[pos.e].num, pos: pos });
    } else {
      b.push({ id: 'first', label: '▶  تشغيل الحلقة الأولى' });
    }
    b.push({ id: 'fav', label: Store.isFav('series', it.id) ? '★  في المفضلة' : '☆  أضف للمفضلة' });
    this.btns = b;
    if (this.btn >= b.length) this.btn = 0;
    var html = '';
    for (var i = 0; i < b.length; i++) {
      html += '<div class="btn' + (this.zone === 'btns' && i === this.btn ? ' focused' : '') + (i === 0 ? ' primary' : '') + '">' + U.esc(b[i].label) + '</div>';
    }
    U.$('sr-btns').innerHTML = html;
  },

  renderSeasons: function () {
    if (!this.data) return;
    var ss = this.data.seasons;
    var html = '';
    for (var i = 0; i < ss.length; i++) {
      var cls = 'stab' + (i === this.season ? ' cur' : '') + (this.zone === 'seasons' && i === this.season ? ' focused' : '');
      html += '<div class="' + cls + '">الموسم ' + U.esc(ss[i].num) + '</div>';
    }
    U.$('sr-seasons').innerHTML = html;
    /* keep the selected tab visible when there are many seasons */
    var tabs = U.$('sr-seasons').children;
    var first = Math.max(0, this.season - 7);
    for (var j = 0; j < tabs.length; j++) tabs[j].style.display = j < first ? 'none' : '';
  },

  renderEpisode: function (ep, i) {
    var h = Store.getHist('e:' + ep.id);
    var badge = '';
    var prog = '';
    if (h && h.done) badge = '<span class="edone">✓ تمت المشاهدة</span>';
    else if (h && h.dur && h.pos > 30000) prog = '<span class="eprog"><i style="width:' + Math.round(h.pos / h.dur * 100) + '%"></i></span>';
    var dur = ep.duration ? String(ep.duration).replace(/^00:/, '') : '';
    return '<div class="eitem" data-i="' + i + '">' +
      U.img(ep.image || this.item.icon, String(ep.num), 'ethumb') +
      '<div class="etext"><div class="enum">الحلقة ' + U.esc(ep.num) + badge + '</div>' +
      '<div class="etitle">' + U.esc(ep.title) + '</div>' +
      (ep.plot ? '<div class="edesc">' + U.esc(ep.plot) + '</div>' : '') + '</div>' +
      (dur ? '<span class="edur">' + U.esc(dur) + '</span>' : '') + prog + '</div>';
  },

  setZone: function (z) {
    this.zone = z;
    this.eps.setActive(z === 'episodes');
    this.renderButtons();
    this.renderSeasons();
  },

  changeSeason: function (d) {
    var n = this.season + d;
    if (!this.data || n < 0 || n >= this.data.seasons.length) return;
    this.season = n;
    this.eps.setItems(this.data.seasons[n].episodes, 0);
    this.renderSeasons();
  },

  play: function (s, e, fromStart) {
    var ep = this.data.seasons[s].episodes[e];
    var h = Store.getHist('e:' + ep.id);
    var startAt = (!fromStart && h && !h.done && h.pos > 30000) ? h.pos : 0;
    App.go('player', { kind: 'episode', series: this.item, seasons: this.data.seasons, seasonIdx: s, epIdx: e, startAt: startAt });
  },

  action: function (b) {
    if (b.id === 'continue') this.play(b.pos.s, b.pos.e, false);
    else if (b.id === 'first') this.play(0, 0, true);
    else if (b.id === 'fav') {
      var on = Store.toggleFav(this.item);
      UI.toast(on ? 'تمت الإضافة إلى المفضلة' : 'تمت الإزالة من المفضلة');
      this.renderButtons();
    }
  },

  onKey: function (k) {
    if (k === 'back') { App.back(); return; }
    if (!this.data || !this.data.seasons.length) return;
    if (k === 'red') { this.action({ id: 'fav' }); return; }

    if (this.zone === 'btns') {
      if (k === 'left' && this.btn < this.btns.length - 1) { this.btn++; this.renderButtons(); }
      else if (k === 'right' && this.btn > 0) { this.btn--; this.renderButtons(); }
      else if (k === 'down') this.setZone('seasons');
      else if (k === 'enter' || k === 'play' || k === 'playpause') this.action(this.btns[this.btn]);
    } else if (this.zone === 'seasons') {
      if (k === 'left') this.changeSeason(1);
      else if (k === 'right') this.changeSeason(-1);
      else if (k === 'up') this.setZone('btns');
      else if (k === 'down' || k === 'enter') this.setZone('episodes');
    } else {
      if (k === 'up' && this.eps.index === 0) this.setZone('seasons');
      else if (k === 'up' || k === 'down' || k === 'chup' || k === 'chdown') this.eps.key(k);
      else if (k === 'enter' || k === 'play' || k === 'playpause') this.play(this.season, this.eps.index, false);
    }
  }
};

