          '<span class="lnum">' + U.esc(it.num || (i + 1)) + '</span>' + U.img(it.icon, it.name, 'llogo') +
          '<span class="lname">' + U.esc(it.name) + '</span></div>';
      }
    });
    this.start();
  };

  S.hide = function () {
    this.closeEps();
    this.clearTimers();
    Player.stop();
    UI.close();
  };

  S.clearTimers = function () {
    clearTimeout(this.osdTimer); clearTimeout(this.zapTimer); clearTimeout(this.numTimer);
    clearTimeout(this.seekTimer); clearInterval(this.saveTimer); clearTimeout(this.subTimer);
    clearInterval(this.epgTimer);
    clearTimeout(this.barTimer);
  };

  S.isLive = function () { return this.p.kind === 'live'; };

  S.channel = function () { return this.p.list[this.p.index]; };

  S.episode = function () {
    var s = this.p.seasons[this.p.seasonIdx];
    return s ? s.episodes[this.p.epIdx] : null;
  };

  /* ------------------------------------------------------------------ */
  S.start = function () {
    var self = this, p = this.p, url, startAt = 0;
    this.retried = false;
    this.paused = false;
    this.dur = 0;
    this.seekTarget = null;
    this.epg = [];
    this.msg('');
    this.subtitle('');
    this.lastTick = undefined;
    this.barIdx = -1;
    this.vz = null;
    clearInterval(this.saveTimer);
    clearInterval(this.epgTimer);

    if (p.kind === 'live') {
      var ch = this.channel();
      this.fmt = Store.getSettings().liveFormat || 'ts';
      url = Xtream.liveUrl(ch, this.fmt);
      Store.setLastChannel(ch);
      this.loadEpg();
      this.epgTimer = setInterval(function () { self.loadEpg(); }, 60000);
    } else if (p.kind === 'movie') {
      url = Xtream.movieUrl(p.item);
      startAt = p.startAt || 0;
    } else {
      url = Xtream.episodeUrl(this.episode());
      startAt = p.startAt || 0;
    }
    this.time = startAt;
    this.url = url;
    this.startedAt = U.now();
    this.renderOSD();
    this.showOSD();
    Player.play(url, { startAt: startAt, live: p.kind === 'live', on: function (e, d) { self.onPlayer(e, d); } });
    if (!this.isLive()) this.saveTimer = setInterval(function () { self.save(); }, 10000);
  };

  S.onPlayer = function (evt, data) {
    var self = this;
    switch (evt) {
      case 'buffer':
        this.center(data ? 'buffer' : (this.paused ? 'pause' : ''));
        break;
      case 'ready':
        this.p.busyWaits = 0;
        this.dur = data || 0;
        this.updateProgress();
        break;
      case 'state':
        this.paused = data === 'paused';
        this.center(this.paused ? 'pause' : '');
        if (this.paused) this.showOSD(true); else this.showOSD();
        this.renderBottom();
        break;
      case 'time':
        /* some streams never send "buffering complete": moving time means it plays */
        if (this.bufferShown && this.lastTick !== undefined && data > this.lastTick) this.center(this.paused ? 'pause' : '');
        this.lastTick = data;
        this.time = data;
        if (this.seekTarget === null) this.updateProgress();
        break;
      case 'subtitle':
        this.subtitle(data.text, data.duration);
        break;
      case 'ended':
        if (this.isLive()) {
          /* a live stream "ended": reconnect, unless it keeps dropping right away */
          if (U.now() - this.startedAt < 8000) { this.retried = true; this.onError('ended'); }
          else setTimeout(function () { if (App.current() === 'player' && self.isLive()) self.start(); }, 1000);
        } else this.finished();
        break;
      case 'error':
        this.onError(data);
        break;
    }
  };

  S.onError = function (detail) {
    if (this.isLive() && !this.retried) {
      /* try the other stream format once (TS <-> HLS) */
      var self = this;
      this.retried = true;
      this.fmt = this.fmt === 'ts' ? 'm3u8' : 'ts';
      Player.play(Xtream.liveUrl(this.channel(), this.fmt), { on: function (e, d) { self.onPlayer(e, d); } });
      return;
    }
    if (!this.isLive() && this.retriedUrl !== this.url) {
      /* a movie / episode: the server often refuses the first try (or the list gave the wrong
         file type): try again from the same moment, with the file type the server gives */
      var me = this, p = this.p;
      this.retriedUrl = this.url;
      this.center('buffer');
      var again = function () {
        if (App.current() !== 'player' || me.p !== p) return;
        p.startAt = me.time;
        me.start();
      };
      if (p.kind === 'movie' && p.item) {
        Xtream.getVodInfo(p.item.id, function (err, d) {
          var ext = d && d.movie_data && d.movie_data.container_extension;
          if (ext) p.item.ext = ext;
          setTimeout(again, 1500);
        });
      } else setTimeout(again, 1500);
      return;
    }
    this.center('');
    if (this.isLive()) {
      this.msg('تعذّر تشغيل هذه القناة حالياً', 'جرّب قناة أخرى أو غيّر صيغة البث من الإعدادات', detail);
    } else this.explainError(detail);
