  };

  /* why a movie / episode does not play, in words, with the TV's own error code underneath */
  S.explainError = function (detail) {
    var self = this, d = String(detail || ''), title = 'تعذّر تشغيل هذا المحتوى';
    var sub = 'تأكد من الاتصال أو جرّب لاحقاً';
    if (/NOT_SUPPORTED|UNSUPPORTED|CODEC|FORMAT/i.test(d)) sub = 'صيغة الصوت أو الصورة في هذا الملف غير مدعومة على هذه الشاشة';
    else if (/CONNECTION|NETWORK|INVALID_URI|TIMEOUT|404|403/i.test(d)) sub = 'السيرفر لم يرسل الملف — غالباً الملف غير متاح عند المزوّد الآن';
    this.msg(title, sub, d);
    /* the subscription may be busy on another screen */
    var acc = Xtream.account();
    if (!acc) return;
    Xtream.probe(acc, function (err, data) {
      if (App.current() !== 'player' || Player.state() !== 'error') return;
      if (err && err.code === 'expired') { self.msg(title, 'انتهى الاشتراك عند المزوّد', d); return; }
      var ui = data && data.user_info;
      var max = ui ? parseInt(ui.max_connections, 10) : 0, act = ui ? parseInt(ui.active_cons, 10) : 0;
      if (max > 0 && act >= max) self.waitFree(title, d, 0);
    });
  };

  /* The subscription is full. Usually it is this TV's own previous video: the provider takes a
     few seconds to count it as stopped (one-screen subscriptions, when moving to the next episode).
     Wait for the place to free up and start by itself; say "another screen" only if it stays full. */
  S.waitFree = function (title, d, n) {
    var self = this, p = this.p, acc = Xtream.account();
    p.busyWaits = (p.busyWaits || 0) + (n === 0 ? 1 : 0);
    if (!acc || n >= 12 || p.busyWaits > 2) {
      self.msg(title, 'الاشتراك مستخدم الآن على جهاز آخر — أوقف التشغيل على الجهاز الآخر ثم جرّب مرة أخرى', d);
      return;
    }
    self.msg('لحظات ويبدأ التشغيل…', 'المزوّد لم يُغلق التشغيل السابق بعد — سيبدأ تلقائياً خلال ثوانٍ', '');
    self.center('buffer');
    setTimeout(function () {
      if (App.current() !== 'player' || self.p !== p) return;
      Xtream.probe(acc, function (err, data) {
        if (App.current() !== 'player' || self.p !== p) return;
        var ui = data && data.user_info;
        var max = ui ? parseInt(ui.max_connections, 10) : 0, act = ui ? parseInt(ui.active_cons, 10) : 0;
        if (max > 0 && act >= max) { self.waitFree(title, d, n + 1); return; }
