    }, 1600);
  };

  /* ---------------- VOD seeking ---------------- */
  /* left / right move the position; the jump happens by itself a moment
     after the last press (holding the key moves further before jumping) */
  S.seekBy = function (sec, fixed) {
    var self = this;
    var dur = Player.getDuration() || this.dur;
    if (!dur) return;
    var first = this.seekTarget === null;
    var base = first ? (Player.getTime() || this.time) : this.seekTarget;
    /* holding the key moves faster: 10 s, then 30 s, then 60 s steps */
    var dir = sec > 0 ? 1 : -1;
    if (first || dir !== this.seekDir) this.seekSteps = 0;
    this.seekDir = dir;
    this.seekSteps++;
    var step = fixed || Math.abs(sec) > 10 ? Math.abs(sec) : (this.seekSteps > 12 ? 60 : (this.seekSteps > 5 ? 30 : 10));
    this.seekTarget = U.clamp(base + dir * step * 1000, 0, dur - 3000);
    this.showOSD(true);
    this.updateProgress(this.seekTarget);
    this.seekHint();
    clearTimeout(this.seekTimer);
    this.seekTimer = setTimeout(function () { self.commitSeek(); }, 800);
  };

  S.seekHint = function () {
    var hint = U.$('pl-keyhint');
    if (!hint || this.seekTarget === null) return;
    var d = Math.round((this.seekTarget - (Player.getTime() || this.time)) / 1000);
    var txt = (d >= 0 ? '+' : '-') + U.fmtTime(Math.abs(d) * 1000);
    hint.innerHTML = (d >= 0 ? 'تقديم إلى ' : 'ترجيع إلى ') + U.fmtTime(this.seekTarget) +
      ' <span class="seek-delta" dir="ltr">(' + txt + ')</span>';
  };

  S.commitSeek = function () {
    if (this.seekTarget === null) return false;
    clearTimeout(this.seekTimer);
    var t = this.seekTarget;
    this.seekTarget = null;
    this.time = t;
    Player.seekTo(t);
    this.updateProgress();
    this.drawBar();
    this.showOSD();
    return true;
  };

  S.cancelSeek = function () {
    if (this.seekTarget === null) return false;
    clearTimeout(this.seekTimer);
    this.seekTarget = null;
    this.updateProgress();
    this.drawBar();
    this.showOSD();
    return true;
  };


  /* ---------------- OSD rendering ---------------- */
  S.renderOSD = function () {
    var p = this.p, h = '';
    if (p.kind === 'live') {
      var ch = this.channel();
      var fav = Store.isFav('live', ch.id) ? '<span class="pl-fav">' + STAR + '</span>' : '';
      h = '<div class="pl-ch"><span class="pl-chnum">' + U.esc(ch.num || (p.index + 1)) + '</span>' +
        U.img(ch.icon, ch.name, 'pl-logo') +
        '<div><div class="pl-title">' + U.esc(ch.name) + fav + '</div>' +
        '<div class="pl-subtitle">' + U.esc(p.catName || '') + '</div></div></div>';
    } else if (p.kind === 'movie') {
      h = '<div class="pl-ch"><div><div class="pl-title">' + U.esc(p.item.name) + '</div>' +
        '<div class="pl-subtitle">فيلم</div></div></div>';
    } else {
      var ep = this.episode(), s = p.seasons[p.seasonIdx];
      h = '<div class="pl-ch"><div><div class="pl-title">' + U.esc(p.series.name) + '</div>' +
        '<div class="pl-subtitle">الموسم ' + U.esc(s.num) + ' · الحلقة ' + U.esc(ep.num) +
        (ep.title ? ' — ' + U.esc(ep.title) : '') + '</div></div></div>';
    }
    if (p.kind === 'live') {
      U.$('pl-top').innerHTML = h + '<div class="clock">' + UI.clockText() + '</div>';
    } else {
      /* movies / episodes: round option buttons at the top */
      this.tools = this.vodTools();
      var t = '<div class="pl-tools">';
      for (var i = 0; i < this.tools.length; i++) {
        t += '<div class="pl-tool" data-t="' + i + '">' + this.tools[i].icon + '<span class="tl">' + U.esc(this.tools[i].label) + '</span></div>';
      }
      t += '<div class="clock">' + UI.clockText() + '</div></div>';
      U.$('pl-top').innerHTML = h + t;
    }
    this.renderBottom();
  };

  S.renderBottom = function () {
    var h = '';
    if (this.isLive()) {
      if (this.epg.length) {
        var now = this.epg[0], next = this.epg[1];
        var pct = now.end > now.start ? U.clamp((U.now() - now.start) / (now.end - now.start), 0, 1) : 0;
        h += '<div class="pl-epg"><div class="pl-epg-now">' +
          '<span class="chip now">الآن</span><b>' + U.esc(now.title) + '</b>' +
          '<span class="pl-epg-time">' + U.fmtClock(new Date(now.start)) + ' - ' + U.fmtClock(new Date(now.end)) + '</span></div>' +
          '<div class="bar" dir="ltr"><i style="width:' + Math.round(pct * 100) + '%"></i></div>';
        if (next) h += '<div class="pl-epg-next"><span class="chip">التالي</span>' + U.esc(next.title) +
          '<span class="pl-epg-time">' + U.fmtClock(new Date(next.start)) + '</span></div>';
        h += '</div>';
      }
      var fav = Store.isFav('live', this.channel().id);
      this.barItems = [
        { a: 'channels', icon: ICON.list, label: 'القنوات' },
        { a: 'subs', icon: ICON.subs, label: 'الترجمة', dot: 'yellow' },
        { a: 'aspect', icon: ICON.aspect, label: 'أبعاد الشاشة', dot: 'blue' },
        { a: 'fav', icon: STAR, label: fav ? 'إزالة من المفضلة' : 'إضافة للمفضلة', dot: 'red' }
      ];
      h += this.barHtml();
    } else {
      h += '<div class="pl-progress" dir="ltr">' +
        '<span class="pl-cur" id="pl-cur">00:00</span>' +
        '<div class="bar big"><i id="pl-fill"></i><b id="pl-knob"></b></div>' +
        '<span class="pl-dur" id="pl-dur">--:--</span></div>';
      /* media buttons, laid out left-to-right like every player */
      this.ctrls = this.vodCtrls();
      h += '<div class="pl-ctrls" dir="ltr">';
      for (var c = 0; c < this.ctrls.length; c++) {
        var b = this.ctrls[c];
        if (b.words) { h += '<div class="pl-c words" data-c="' + c + '"><span class="pw" dir="rtl">' + U.esc(b.label) + '</span></div>'; continue; }
        h += '<div class="pl-c ' + b.cls + '" data-c="' + c + '">' + b.icon + (b.ten ? '<b>10</b>' : '') +
          '<span class="tl">' + U.esc(b.label) + '</span></div>';
      }
      h += '</div><div class="pl-keyhint" id="pl-keyhint"></div>';
      this.barItems = [];
    }
    U.$('pl-bottom').innerHTML = h;
    if (this.isLive() && this.barIdx >= this.barItems.length) this.barIdx = this.barItems.length - 1;
    this.drawBar();
    this.updateProgress();
  };

  /* ---------------- bottom button bar (reach it with the arrows) ---------------- */
  S.barHtml = function () {
    var h = '<div class="pl-bar">';
    for (var i = 0; i < this.barItems.length; i++) {
      var b = this.barItems[i];
      h += '<div class="pl-btn" data-b="' + i + '">' + b.icon + '<span>' + U.esc(b.label) + '</span>' +
        (b.dot ? '<i class="dot ' + b.dot + '"></i>' : '') + '</div>';
    }
    return h + '</div><div class="pl-keyhint" id="pl-keyhint"></div>';
  };

  S.drawBar = function () {
    if (!this.isLive()) { this.drawVod(); return; }
    var btns = U.$('pl-bottom').querySelectorAll('.pl-btn');
    for (var i = 0; i < btns.length; i++) U.toggleClass(btns[i], 'focused', i === this.barIdx);
    var hint = U.$('pl-keyhint');
    if (!hint) return;
    if (this.barIdx >= 0) hint.innerHTML = '<span class="kb" dir="ltr">◀ ▶</span> تنقّل <span class="kb">OK</span> اختيار <span class="kb">▲</span> رجوع';
    else if (this.isLive()) hint.innerHTML = '<span class="kb" dir="ltr">▲ ▼</span> تغيير القناة <span class="kb" dir="ltr">◀ ▶</span> الخيارات <span class="kb">OK</span> قائمة القنوات';
    else hint.innerHTML = '<span class="kb" dir="ltr">◀ ▶</span> ترجيع / تقديم <span class="kb">OK</span> إيقاف / تشغيل <span class="kb">▼</span> الخيارات';
    if (this.barIdx < 0 && this.seekTarget !== null) this.seekHint();
  };

  S.enterBar = function () {
    this.barIdx = 0;
    this.showOSD(true);
    this.drawBar();
    this.armBar();
  };

  S.leaveBar = function (hide) {
    this.barIdx = -1;
    this.vz = null;
    clearTimeout(this.barTimer);
    this.drawBar();
    if (hide) this.hideOSD(); else this.showOSD();
  };

  /* drop the focus after 10 s without a key */
  S.armBar = function () {
    var self = this;
    clearTimeout(this.barTimer);
    this.barTimer = setTimeout(function () { if (!UI.modal()) self.leaveBar(true); else self.armBar(); }, 10000);
  };

  /* a menu opened from the bar closed: come back to the bar */
  S.menuClosed = function () {
    if (this.barIdx < 0 || App.current() !== 'player') return;
    this.showOSD(true);
    this.drawBar();
    this.armBar();
  };

  S.barKey = function (k) {
    var n = this.barItems.length;
    this.armBar();
    switch (k) {
      case 'left': if (this.barIdx < n - 1) { this.barIdx++; this.drawBar(); } return true;
      case 'right': if (this.barIdx > 0) { this.barIdx--; this.drawBar(); } return true;
      case 'enter': this.barAction(this.barItems[this.barIdx].a); return true;
      case 'up': case 'back': this.leaveBar(false); return true;
      case 'down': if (this.isLive()) this.leaveBar(false); return true;
    }
    return false;
  };

  S.barAction = function (a) {
    switch (a) {
      case 'toggle':
        if (Player.state() === 'error') { this.p.startAt = this.time; this.start(); break; }
        Player.toggle(); this.showOSD(true);
        break;
      case 'prevEp': this.changeEpisode(-1); break;
      case 'nextEp': this.changeEpisode(1); break;
      case 'audio': this.audioMenu(); break;
      case 'subs': this.subsMenu(); break;
      case 'aspect': this.aspectMenu(); break;
      case 'channels': this.barIdx = -1; this.openZap(); break;
      case 'fav':
        var on = Store.toggleFav(this.channel());
        UI.toast(on ? 'تمت إضافة القناة للمفضلة' : 'تمت إزالة القناة من المفضلة');
        this.renderOSD(); this.showOSD(true);
        break;
    }
  };

  S.changeEpisode = function (d) {
    if (this.p.kind !== 'episode') return;
    var n = this.nextEp(d);
    if (!n) { UI.toast(d > 0 ? 'هذه آخر حلقة' : 'هذه أول حلقة'); return; }
    this.save();
    this.p.seasonIdx = n.s; this.p.epIdx = n.e;
    var h = Store.getHist('e:' + this.episode().id);
    this.p.startAt = h && !h.done && h.pos > 30000 ? h.pos : 0;
    var keep = this.barIdx, kz = this.vz;
    this.start();
    if (keep >= 0) { this.barIdx = keep; this.vz = kz; this.showOSD(true); this.drawBar(); this.armBar(); }
  };

  /* ================= movies / episodes: top options + media buttons ================= */
  S.vodTools = function () {
    var t = [];
    if (this.p.kind === 'episode') t.push({ a: 'episodes', icon: ICON.eps, label: 'الحلقات' });
    t.push({ a: 'subs', icon: ICON.subs, label: 'الترجمة' });
    t.push({ a: 'aspect', icon: ICON.aspect, label: 'أبعاد الشاشة' });
    return t;
  };

  S.vodCtrls = function () {
    var ep = this.p.kind === 'episode', c = [];
    /* car screen: the episode buttons say what they do instead of showing an arrow */
    var words = !!(window.ANDROID_APP && !window.IS_TV);
    if (ep) c.push({ a: 'prevEp', icon: ICON.prev, cls: 'sm', label: 'الحلقة السابقة', words: words });
    c.push({ a: 'rw10', icon: ICON.replay, cls: 'md', ten: true, label: 'رجوع 10 ث' });
    c.push({ a: 'toggle', icon: this.paused ? PLAY : PAUSE, cls: 'lg', label: this.paused ? 'تشغيل' : 'إيقاف مؤقت' });
    c.push({ a: 'ff10', icon: ICON.replay, cls: 'md ff', ten: true, label: 'تقديم 10 ث' });
    if (ep) c.push({ a: 'nextEp', icon: ICON.next, cls: 'sm', label: 'الحلقة التالية', words: words });
    return c;
  };

  S.playIndex = function () {
    for (var i = 0; i < (this.ctrls || []).length; i++) if (this.ctrls[i].a === 'toggle') return i;
    return 0;
  };

  S.drawVod = function () {
    var i, el = U.$('pl-top').querySelectorAll('.pl-tool');
    for (i = 0; i < el.length; i++) U.toggleClass(el[i], 'focused', this.vz === 'top' && i === this.vt);
    el = U.$('pl-bottom').querySelectorAll('.pl-c');
    for (i = 0; i < el.length; i++) U.toggleClass(el[i], 'focused', this.vz === 'ctrl' && i === this.vc);
    var hint = U.$('pl-keyhint');
    if (!hint) return;
    if (this.seekTarget !== null) { this.seekHint(); return; }
    if (this.vz === 'ctrl') hint.innerHTML = '<span class="kb" dir="ltr">◀ ▶</span> تنقّل <span class="kb">OK</span> اختيار <span class="kb">▲</span> الخيارات فوق';
    else if (this.vz === 'top') hint.innerHTML = '<span class="kb" dir="ltr">◀ ▶</span> تنقّل <span class="kb">OK</span> اختيار <span class="kb">▼</span> أزرار التشغيل';
    else hint.innerHTML = '<span class="kb" dir="ltr">◀ ▶</span> ترجيع / تقديم <span class="kb">OK</span> إيقاف / تشغيل <span class="kb">▼</span> أزرار التشغيل <span class="kb">▲</span> الخيارات' +
      (this.p.kind === 'episode' ? ' <span class="kb green"></span> الحلقات' : '');
  };

  S.enterVod = function (z) {
    this.vz = z;
    this.barIdx = 0;
    if (z === 'ctrl') this.vc = this.playIndex();
    else this.vt = 0;
    this.showOSD(true);
    this.drawVod();
    this.armBar();
  };

  S.vodKey = function (k) {
    this.armBar();
    if (this.vz === 'ctrl') {
      var n = this.ctrls.length;
      if (k === 'left') { if (this.vc > 0) { this.vc--; this.drawVod(); } return true; }
      if (k === 'right') { if (this.vc < n - 1) { this.vc++; this.drawVod(); } return true; }
      if (k === 'up') { this.vz = 'top'; this.vt = this.vt || 0; this.drawVod(); return true; }
      if (k === 'down' || k === 'back') { this.leaveBar(k === 'down'); return true; }
      if (k === 'enter') { this.vodAction(this.ctrls[this.vc].a); return true; }
    } else if (this.vz === 'top') {
      var m = this.tools.length;
      if (k === 'left') { if (this.vt < m - 1) { this.vt++; this.drawVod(); } return true; }
      if (k === 'right') { if (this.vt > 0) { this.vt--; this.drawVod(); } return true; }
      if (k === 'down') { this.vz = 'ctrl'; if (this.vc === undefined || this.vc >= this.ctrls.length) this.vc = this.playIndex(); this.drawVod(); return true; }
      if (k === 'up' || k === 'back') { this.leaveBar(false); return true; }
      if (k === 'enter') { this.vodAction(this.tools[this.vt].a); return true; }
    }
    return false;
  };

  S.vodAction = function (a) {
    if (a === 'rw10') { this.seekBy(-10, true); return; }
    if (a === 'ff10') { this.seekBy(10, true); return; }
    if (a === 'episodes') { this.openEps(); return; }
    this.barAction(a);
  };

  /* ================= episodes panel (inside the player) ================= */
  S.openEps = function () {
    if (this.p.kind !== 'episode') return;
    var self = this;
    if (!this.epsList) {
      this.epsList = new VList(U.$('eps-list'), {
        rows: 5, extra: 1, rowClass: 'eprow',
        render: function (ep, i) { return self.renderEp(ep, i); }
      });
    }
    this.hideOSD();
    this.epsOpen = true;
    this.epsSeason = this.p.seasonIdx;
    U.addClass(U.$('pl-eps'), 'open');
    this.epsList.setActive(true);
    this.drawEps(this.p.epIdx);
  };

  S.closeEps = function () {
    if (!this.epsOpen) return;
    this.epsOpen = false;
    U.removeClass(U.$('pl-eps'), 'open');
    if (this.epsList) this.epsList.setActive(false);
  };

  S.drawEps = function (focus) {
    var ss = this.p.seasons, h = '';
    U.$('eps-head').innerHTML = '<div><b>' + U.esc(this.p.series.name) + '</b><span>' + ss.length +
      (ss.length > 1 ? ' مواسم' : ' موسم') + '</span></div>';
    var first = Math.max(0, Math.min(this.epsSeason - 2, ss.length - 5));
    for (var i = first; i < ss.length; i++) {
      h += '<span class="eps-tab' + (i === this.epsSeason ? ' cur' : '') + (i === this.p.seasonIdx ? ' playing' : '') + '">الموسم ' + U.esc(ss[i].num) + '</span>';
    }
    U.$('eps-seasons').innerHTML = (first > 0 ? '<span class="eps-more">‹</span>' : '') + h;
    this.epsList.setItems(ss[this.epsSeason].episodes, focus || 0);
  };

  S.renderEp = function (ep, i) {
    var playing = this.epsSeason === this.p.seasonIdx && i === this.p.epIdx;
    var h = Store.getHist('e:' + ep.id), badge = '', pct = 0;
    if (playing) {
      badge = '<span class="ep-now">يعرض الآن</span>';
      var d = Player.getDuration() || this.dur;
      pct = d ? (Player.getTime() || this.time) / d : 0;
    } else if (h && h.done) {
      badge = '<span class="ep-done">✓ تمت المشاهدة</span>';
    } else if (h && h.dur && h.pos > 30000) {
      pct = h.pos / h.dur;
    }
    var dur = ep.duration ? String(ep.duration).replace(/^00:/, '') : '';
    return '<div class="epitem' + (playing ? ' playing' : '') + '" data-i="' + i + '">' +
      U.img(ep.image || this.p.series.icon, String(ep.num), 'epthumb') +
      '<div class="eptext"><div class="epnum">الحلقة ' + U.esc(ep.num) + badge + '</div>' +
      '<div class="eptitle">' + U.esc(ep.title || ('الحلقة ' + ep.num)) + '</div>' +
      (dur ? '<div class="epdur">' + U.esc(dur) + '</div>' : '') + '</div>' +
      (pct > 0 ? '<span class="epprog"><i style="width:' + Math.round(U.clamp(pct, 0.02, 1) * 100) + '%"></i></span>' : '') +
      '</div>';
  };

  S.epsKey = function (k) {
    var ss = this.p.seasons;
    if (k === 'up' || k === 'down' || k === 'chup' || k === 'chdown') this.epsList.key(k);
    else if (k === 'left') { if (this.epsSeason < ss.length - 1) { this.epsSeason++; this.drawEps(0); } }
    else if (k === 'right') { if (this.epsSeason > 0) { this.epsSeason--; this.drawEps(0); } }
    else if (k === 'enter') {
      var e = this.epsList.index;
      if (this.epsSeason === this.p.seasonIdx && e === this.p.epIdx) { this.closeEps(); this.showOSD(); }
      else this.playEp(this.epsSeason, e);
    }
    else if (k === 'back' || k === 'green' || k === 'info') { this.closeEps(); this.showOSD(); }
    else if (k === 'playpause' || k === 'play' || k === 'pause') Player.toggle();
  };

  S.playEp = function (s, e) {
    this.closeEps();
    this.save();
    this.p.seasonIdx = s; this.p.epIdx = e;
    var h = Store.getHist('e:' + this.episode().id);
    this.p.startAt = h && !h.done && h.pos > 30000 ? h.pos : 0;
    this.start();
  };

  S.updateProgress = function (at) {
    if (this.isLive()) return;
    var fill = U.$('pl-fill');
    if (!fill) return;
    var dur = Player.getDuration() || this.dur;
    var t = at !== undefined ? at : this.time;
    var pct = dur ? U.clamp(t / dur, 0, 1) * 100 : 0;
    fill.style.width = pct + '%';
    U.$('pl-knob').style.left = pct + '%';
    U.$('pl-cur').innerHTML = U.fmtTime(t);
    U.$('pl-dur').innerHTML = dur ? U.fmtTime(dur) : '--:--';
    U.toggleClass(U.$('pl-cur'), 'seeking', at !== undefined);
  };

  S.showOSD = function (sticky) {
    var self = this;
    var top = U.$('pl-top').querySelector('.clock');
    if (top) top.innerHTML = UI.clockText();
    U.addClass(U.$('pl-osd'), 'show');
    clearTimeout(this.osdTimer);
    if (!sticky && !this.paused && this.barIdx < 0) this.osdTimer = setTimeout(function () { self.hideOSD(); }, 5000);
  };

  S.hideOSD = function () {
    clearTimeout(this.osdTimer);
    if (this.barIdx >= 0) { this.barIdx = -1; this.vz = null; clearTimeout(this.barTimer); this.drawBar(); }
    U.removeClass(U.$('pl-osd'), 'show');
  };

  S.osdVisible = function () { return U.$('pl-osd').className.indexOf('show') !== -1; };

  S.center = function (what) {
    var el = U.$('pl-center');
    this.bufferShown = what === 'buffer';
    if (what === 'buffer') el.innerHTML = '<div class="spinner"></div>';
    else if (what === 'pause') el.innerHTML = '<div class="pl-bigicon">' + PAUSE + '</div>';
    else el.innerHTML = '';
  };

  S.msg = function (title, sub, code) {
    var el = U.$('pl-msg');
    if (!title) { el.style.display = 'none'; return; }
    el.innerHTML = '<b>' + U.esc(title) + '</b>' + (sub ? '<span>' + U.esc(sub) + '</span>' : '') +
      (code ? '<i class="pl-code" dir="ltr">' + U.esc(String(code).slice(0, 60)) + '</i>' : '');
    el.style.display = 'block';
  };

  S.subtitle = function (text, ms) {
    var el = U.$('pl-sub');
    clearTimeout(this.subTimer);
    if (!text) { el.innerHTML = ''; el.style.display = 'none'; return; }
    el.innerHTML = U.esc(text).replace(/\n/g, '<br>');
    el.style.display = 'block';
    this.subTimer = setTimeout(function () { el.style.display = 'none'; }, ms > 0 ? ms : 4000);
  };

  /* ---------------- aspect ratio menu (live preview while moving) ---------------- */
  S.aspectMenu = function () {
    var cur = Player.aspectKey();
    var list = Player.aspectList(), items = [];
    for (var i = 0; i < list.length; i++) {
      items.push({ label: list[i].name, sub: list[i].desc, value: list[i].key, selected: list[i].key === cur });
    }
    var self = this, fromBar = this.barIdx, fromZone = this.vz, first = true;
    U.removeClass(U.$('pl-osd'), 'show');           /* keep the picture clear */
    UI.menu({
      title: 'أبعاد الشاشة', items: items, side: true, closeKey: 'blue',
      hint: 'التغيير يتطبّق فوراً وأنت بتتحرك ▲▼ · OK أو رجوع للإغلاق',
      /* every move applies (and saves) the mode right away */
      onFocus: function (v) {
        if (first) { first = false; return; }      /* the menu opening is not a move */
        Player.setAspect(v);
        if (Player.aspectZoom(v) > 1 && !Player.zoomWorks()) UI.toast('التكبير غير مدعوم على هذا التلفزيون');
      },
      onSelect: function (v) {
        if (v !== null && v !== Player.aspectKey()) Player.setAspect(v);
        UI.toast('أبعاد الشاشة: ' + Player.aspectName());
        self.barIdx = fromBar;
        self.vz = fromZone;
        self.menuClosed();
      }
    });
  };

  /* ---------------- tracks ---------------- */
  S.audioMenu = function () {
    var self = this;
    var tr = Player.getTracks('AUDIO');
    if (tr.length < 2) { UI.toast(tr.length ? 'يوجد مسار صوت واحد فقط' : 'لا توجد مسارات صوت إضافية'); return; }
    var items = [];
    for (var i = 0; i < tr.length; i++) items.push({ label: tr[i].label, value: tr[i].index, selected: tr[i].selected });
    UI.menu({
      title: 'مسار الصوت', items: items,
      onSelect: function (v) { if (v !== null && Player.selectTrack('AUDIO', v)) UI.toast('تم تغيير الصوت'); self.menuClosed(); }
    });
  };

  S.subsMenu = function () {
    var self = this;
    var tr = Player.getTracks('TEXT');
    if (!tr.length) { UI.toast('لا توجد ترجمة مدمجة في هذا المحتوى'); return; }
    var items = [{ label: 'بدون ترجمة', value: -1, selected: !Player.subtitlesOn() }];
    for (var i = 0; i < tr.length; i++) items.push({ label: tr[i].label, value: tr[i].index, selected: tr[i].selected });
    UI.menu({
      title: 'الترجمة', items: items,
      onSelect: function (v) {
        if (v === -1) { Player.subtitlesOff(); self.subtitle(''); UI.toast('تم إيقاف الترجمة'); }
        else if (v !== null && Player.selectTrack('TEXT', v)) UI.toast('تم تفعيل الترجمة');
        self.menuClosed();
      }
    });
  };

  /* ---------------- keys ---------------- */
  S.onKey = function (k, e) {
    var live = this.isLive();

    /* episodes panel open: it gets the keys */
    if (this.epsOpen) { this.epsKey(k); return; }

    /* the bottom button bar has the arrows / OK while it is focused */
    if (live && this.barIdx >= 0 && !this.zapOpen && this.barKey(k)) return;
    if (!live && this.vz && this.vodKey(k)) return;

    /* a jump is about to happen: OK does it now, Back cancels it */
    if (!live && this.seekTarget !== null) {
      if (k === 'enter') { this.commitSeek(); return; }
      if (k === 'back') { this.cancelSeek(); return; }
    }

    if (k === 'back' || k === 'stop') {
      if (this.zapOpen && k === 'back') { this.closeZap(); return; }
      this.exit();
      return;
    }
    if (k === 'blue') { this.aspectMenu(); return; }
    if (k === 'green') { if (this.p.kind === 'episode') this.openEps(); else this.audioMenu(); return; }
    if (k === 'yellow') { this.subsMenu(); return; }
    if (k === 'info') { if (this.osdVisible()) this.hideOSD(); else this.showOSD(); return; }

    if (live) {
      if (this.zapOpen) {
        this.armZap();
        if (k === 'up' || k === 'down' || k === 'chup' || k === 'chdown') this.zap.key(k);
        else if (k === 'enter') {
          var i = this.zap.index;
          this.closeZap();
          if (i !== this.p.index) this.zapTo(i); else this.showOSD();
        } else if (k === 'left') this.closeZap();
        return;
      }
      switch (k) {
        case 'up': case 'chup': this.zapTo(this.p.index + 1); break;
        case 'down': case 'chdown': this.zapTo(this.p.index - 1); break;
        case 'enter': this.openZap(); break;
        case 'left': case 'right': this.enterBar(); break;
        case 'digit': this.numKey(Keys.digit(e)); break;
        case 'red':
          var on = Store.toggleFav(this.channel());
          UI.toast(on ? 'تمت إضافة القناة للمفضلة' : 'تمت إزالة القناة من المفضلة');
          this.renderOSD(); this.showOSD();
          break;
        case 'playpause': case 'play': case 'pause': this.showOSD(); break;
      }
      return;
    }

    /* movies / episodes */
    switch (k) {
      case 'enter': case 'playpause':
        if (Player.state() === 'error') { this.p.startAt = this.time; this.start(); break; }
        Player.toggle(); this.showOSD(); break;
      case 'play': Player.resume(); this.showOSD(); break;
      case 'pause': Player.pause(); break;
      case 'right': this.seekBy(10); break;
      case 'left': this.seekBy(-10); break;
      case 'ff': this.seekBy(60); break;
      case 'rw': this.seekBy(-60); break;
      case 'down': this.enterVod('ctrl'); break;
      case 'up': this.enterVod('top'); break;
      case 'chup': this.changeEpisode(1); break;
      case 'chdown': this.changeEpisode(-1); break;
    }
  };
})();

