/* ==========================================================================
   Playlists screen — several Xtream subscriptions on one TV.
   Shows every saved playlist with a live check (works / expired / not
   working), lets you switch to another one or delete one, and adds new
   playlists from the phone by scanning the QR code (or by typing them).
   ========================================================================== */
Screens.playlists = {
  idx: 0,
  status: {},             /* playlist id -> {cls, text} */
  note: '',

  STATUS: {
    connecting: 'جاري تجهيز الرمز...',
    ready: 'في انتظار الجوال...',
    offline: 'خدمة الربط غير متاحة حالياً',
    received: 'تم استلام البيانات ✓'
  },

  show: function (params) {
    this.params = params || {};
    this.note = this.params.message || '';
    this.status = {};
    var act = Store.activePlaylist(), list = Store.getPlaylists();
    this.idx = 0;
    for (var i = 0; i < list.length; i++) if (act && list[i].id === act.id) this.idx = i;
    this.draw();
    this.checkAll();
    this.startPairing();
  },

  resume: function (result) {
    if (result && result.added) {
      var list = Store.getPlaylists();
      for (var i = 0; i < list.length; i++) if (list[i].id === result.added) this.idx = i;
    }
    this.draw();
    this.checkAll();
    this.startPairing();
  },

  hide: function () { Pair.stop(); },

  visibility: function (hidden) {
    if (hidden) Pair.stop();
    else this.startPairing();
  },

  rows: function () { return Store.getPlaylists().concat([{ add: true }]); },

  /* ---------------- drawing ---------------- */
  draw: function () {
    var rows = this.rows(), act = Store.activePlaylist(), h = '';
    if (this.idx >= rows.length) this.idx = rows.length - 1;
    if (this.note) h += '<div class="pls-note">' + U.esc(this.note) + '</div>';
    for (var i = 0; i < rows.length; i++) {
      var r = rows[i], f = i === this.idx ? ' focused' : '';
      if (r.add) {
        h += '<div class="plsrow add' + f + '" data-i="' + i + '"><div class="pls-info"><b>＋  إضافة قائمة يدوياً</b>' +
          '<span class="rtl">اكتب رابط السيرفر واسم المستخدم وكلمة المرور</span></div></div>';
        continue;
      }
      var cur = act && act.id === r.id;
      var st = this.status[r.id] || { cls: 'wait', text: '' };
      h += '<div class="plsrow' + f + (cur ? ' cur' : '') + '" data-i="' + i + '">' +
        '<div class="pls-info"><b>' + U.esc(r.name || 'قائمة ' + (i + 1)) + '</b>' +
        '<span>' + U.esc(r.username) + '  ·  ' + U.esc(r.server) + '</span></div>' +
        '<div class="pls-badges">' + (cur ? '<span class="pls-cur">قيد التشغيل</span>' : '') +
        (st.text ? '<span class="pls-st ' + st.cls + '">' + U.esc(st.text) + '</span>' : '') + '</div></div>';
    }
    var el = U.$('pls-list');
    el.innerHTML = h;
    var n = rows.length - 1;
    U.$('pls-count').innerHTML = n === 1 ? 'قائمة واحدة' : n === 2 ? 'قائمتان' : n + ' قوائم';
    /* keep the focused row visible */
    var row = el.querySelector('.plsrow.focused');
    if (row) {
      if (row.offsetTop + row.offsetHeight > el.scrollTop + el.clientHeight) el.scrollTop = row.offsetTop + row.offsetHeight - el.clientHeight;
      if (row.offsetTop < el.scrollTop) el.scrollTop = row.offsetTop;
    }
  },

  /* ---------------- checking each playlist ---------------- */
  classify: function (err, data) {
    if (err) {
      if (err.code === 'auth') return { cls: 'bad', text: 'بيانات الدخول غير صحيحة' };
      if (err.code === 'expired') return { cls: 'bad', text: 'الاشتراك منتهي' };
      if (err.code === 'banned' || err.code === 'disabled') return { cls: 'bad', text: 'الاشتراك موقوف' };
      return { cls: 'bad', text: 'لا يعمل حالياً' };
    }
    var exp = parseInt(data && data.user_info && data.user_info.exp_date, 10);
    if (exp > 0) {
      var days = Math.ceil((exp * 1000 - U.now()) / 86400000);
      return { cls: days <= 5 ? 'warn' : 'ok', text: '✓ يعمل · ' + (days <= 0 ? 'ينتهي اليوم' : days === 1 ? 'باقي يوم' : days === 2 ? 'باقي يومان' : 'باقي ' + days + (days <= 10 ? ' أيام' : ' يوماً')) };
    }
    return { cls: 'ok', text: '✓ يعمل' };
  },

  checkOne: function (p) {
    var self = this;
    this.status[p.id] = { cls: 'wait', text: 'جاري الفحص...' };
    Xtream.probe(p, function (err, data) {
      self.status[p.id] = self.classify(err, data);
      if (App.current() === 'playlists') self.draw();
    });
  },

  checkAll: function () {
    var list = Store.getPlaylists();
    for (var i = 0; i < list.length; i++) this.checkOne(list[i]);
    this.draw();
  },

  /* ---------------- adding from the phone (QR) ---------------- */
  startPairing: function () {
    var self = this, card = U.$('pls-qr');
    if (!Pair.enabled()) { card.style.display = 'none'; return; }
    card.style.display = '';
    var s = Pair.start({
      onStatus: function (st) { self.pairStatus(st); },
      onCredentials: function (c) { self.fromPhone(c); }
    });
    try { QR.drawCanvas(U.$('pls-qr-canvas'), s.url, { ecl: 'M', px: 300, margin: 3 }); }
    catch (e) { card.style.display = 'none'; }
  },

  pairStatus: function (st) {
    var el = U.$('pls-qr-status');
    el.className = 'qr-status ' + st;
    el.querySelector('span').innerHTML = U.esc(this.STATUS[st] || '');
  },

  fromPhone: function (c) {
    var self = this;
    var p = Xtream.parseServer(c.server);
    var acc = {
      server: p.server || c.server,
      username: String(c.username || p.username || '').replace(/^\s+|\s+$/g, ''),
      password: String(c.password || p.password || '').replace(/^\s+|\s+$/g, '')
    };
    if (!acc.server || !acc.username || !acc.password) { UI.toast('البيانات ناقصة، حاول مرة أخرى'); this.startPairing(); return; }
    UI.loading(true, 'جاري التحقق من قائمة التشغيل...');
    Xtream.probe(acc, function (err, data) {
      UI.loading(false);
      if (err && err.code === 'auth') {
        UI.toast('اسم المستخدم أو كلمة المرور غير صحيحة');
        self.startPairing();
        return;
      }
      var pl = Store.savePlaylist(acc);
      self.status[pl.id] = self.classify(err, data);
      var list = Store.getPlaylists();
      for (var i = 0; i < list.length; i++) if (list[i].id === pl.id) self.idx = i;
      self.note = '';
      self.draw();
      UI.toast(err ? 'تمت إضافة القائمة لكنها لا تعمل حالياً' : 'تمت إضافة قائمة التشغيل ✓');
      /* a fresh code, ready for one more */
      setTimeout(function () { if (App.current() === 'playlists') self.startPairing(); }, 2500);
    });
  },

  /* ---------------- actions ---------------- */
  action: function () {
    var self = this, r = this.rows()[this.idx];
    if (!r) return;
    if (r.add) { App.go('login', { add: true }); return; }
    var act = Store.activePlaylist(), cur = act && act.id === r.id, items = [];
    if (!cur) items.push({ label: 'تشغيل هذه القائمة', value: 'use' });
    items.push({ label: 'فحص الاتصال', value: 'check' });
    items.push({ label: 'حذف القائمة', value: 'del' });
    UI.menu({
      title: r.name || 'قائمة التشغيل', items: items,
      onSelect: function (v) {
        if (v === 'use') self.use(r);
        else if (v === 'check') { self.checkOne(r); self.draw(); }
        else if (v === 'del') self.remove(r);
      }
    });
  },

  use: function (p) {
    Pair.stop();
    Store.usePlaylist(p.id);
    Xtream.clearCache();
    UI.toast('جاري التبديل إلى ' + (p.name || 'القائمة'));
    App.reconnect();
  },

  remove: function (p) {
    var self = this;
    UI.confirm({
      title: 'حذف «' + (p.name || 'القائمة') + '»؟',
      text: 'سيتم حذف هذه القائمة من الجهاز.',
      buttons: [{ label: 'حذف', value: 'yes', danger: true }, { label: 'إلغاء', value: 'no' }],
      index: 1,
      onSelect: function (v) {
        if (v !== 'yes') return;
        var before = Store.activePlaylist();
        var now = Store.removePlaylist(p.id);
        UI.toast('تم حذف القائمة');
        if (!now) { Player.stop(); Xtream.clearCache(); App.go('login', {}, { reset: true }); return; }
        if (!before || before.id !== now.id) { Xtream.clearCache(); App.reconnect(); return; }
        self.draw();
      }
    });
  },

  onKey: function (k) {
    var n = this.rows().length;
    if (k === 'up' && this.idx > 0) { this.idx--; this.draw(); }
    else if (k === 'down' && this.idx < n - 1) { this.idx++; this.draw(); }
    else if (k === 'enter') this.action();
    else if (k === 'red') { var r = this.rows()[this.idx]; if (r && !r.add) this.remove(r); }
    else if (k === 'back') App.back();
  }
};

/* ==========================================================================
   ota.js — updates the app over the internet, no laptop needed.
   The app's own code (page, styles, screens) is downloaded from
   https://mabdullah-apps.github.io/iptv/<platform>/ and kept on the device;
   boot.js starts that newer code the next time the app opens.
   Never part of an update: js/config.js (the private built-in account),
   the saved subscriptions, favourites and settings - those stay on the device.
   ========================================================================== */
var OTA = (function () {
  var BOOT = window.OTA_BOOT || { app: 'iptv', platform: 'tizen', shell: 1, base: '0', running: '0', from: 'package', notes: [] };
  var cfg = window.IPTV_CONFIG || window.RADIO_TEST || {};   /* tests only */
  var BASE_URL = (cfg.otaUrl || 'https://mabdullah-apps.github.io/' + (BOOT.app || 'iptv') + '/') + BOOT.platform + '/';
  var FIRST_CHECK = cfg.otaFirstCheck || 45 * 1000;      /* after the app opens */
  var EVERY = 6 * 3600 * 1000;                            /* then every 6 hours */

  var st = { status: 'idle', latest: null, error: '', checkedAt: 0, busy: false };

  function cmp(a, b) {
    var x = String(a || '0').split('.'), y = String(b || '0').split('.');
    for (var i = 0; i < Math.max(x.length, y.length); i++) {
      var d = (parseInt(x[i], 10) || 0) - (parseInt(y[i], 10) || 0);
      if (d) return d > 0 ? 1 : -1;
    }
    return 0;
  }
  function ls(k, v) {
    try {
      if (v === undefined) return localStorage.getItem(k);
      if (v === null) localStorage.removeItem(k); else localStorage.setItem(k, v);
    } catch (e) {}
    return null;
  }
  function now() { return new Date().getTime(); }

  /* FNV-1a over the text, the same sum the publishing script writes */
  function sum(s) {
    var h = 0x811c9dc5;
    for (var i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
    }
    return ('0000000' + h.toString(16)).slice(-8);
  }

  function get(url, cb) {
    var x = new XMLHttpRequest(), done = false;
    function end(err, txt) { if (done) return; done = true; cb(err, txt); }
    try {
      x.open('GET', url + (url.indexOf('?') < 0 ? '?' : '&') + 't=' + now(), true);
      x.timeout = 30000;
      x.onload = function () { if (x.status >= 200 && x.status < 300) end(null, x.responseText); else end('http ' + x.status); };
      x.onerror = function () { end('network'); };
      x.ontimeout = function () { end('timeout'); };
      x.send();
    } catch (e) { end('network'); }
  }

  /* the version that is downloaded and will start next time (if newer than the running one) */
  function ready() {
    var v = ls('ota.ready');
    return v && cmp(v, BOOT.running) > 0 && v !== ls('ota.bad') ? v : '';
  }

  function auto() { return ls('ota.auto') !== 'off'; }
  function setAuto(on) { ls('ota.auto', on ? null : 'off'); }

  /* cb({ status: 'latest' | 'ready' | 'needShell' | 'error', version, notes, fresh }) */
  function check(cb) {
    cb = cb || function () {};
    if (st.busy) { cb({ status: 'busy' }); return; }
    st.busy = true;
    get(BASE_URL + 'latest.json', function (err, txt) {
      var L = null;
      if (!err) { try { L = JSON.parse(txt); } catch (e) { err = 'bad file'; } }
      if (err || !L || !L.version) { st.busy = false; st.status = 'error'; st.error = err || 'bad file'; cb({ status: 'error' }); return; }
      st.latest = L;
      st.checkedAt = now();
      var have = ready() || BOOT.running;
      if (cmp(L.version, have) <= 0 || L.version === ls('ota.bad')) {
        st.busy = false;
        st.status = ready() ? 'ready' : 'latest';
        cb({ status: st.status, version: ready() || BOOT.running, notes: readyNotes() });
        return;
      }
      if ((L.minShell || 1) > BOOT.shell) {
        st.busy = false; st.status = 'needShell';
        cb({ status: 'needShell', version: L.version, notes: L.notes || [] });
        return;
      }
      get(BASE_URL + L.bundle, function (err2, txt2) {
        st.busy = false;
        var B = null;
        if (!err2) { try { B = JSON.parse(txt2); } catch (e) { err2 = 'bad file'; } }
        var ok = B && B.version === L.version && B.html && B.css !== undefined && B.js && B.js.length;
        if (ok) {
          var all = B.html + B.css;
          for (var i = 0; i < B.js.length; i++) all += B.js[i].code;
          ok = sum(all) === L.sum;
        }
        if (err2 || !ok) { st.status = 'error'; st.error = err2 || 'damaged download'; cb({ status: 'error' }); return; }
        try {
          localStorage.setItem('ota.bundle', txt2);
        } catch (e) {
          st.status = 'error'; st.error = 'no space'; cb({ status: 'error' }); return;
        }
        ls('ota.ready', B.version);
        ls('ota.readyNotes', JSON.stringify(B.notes || []));
        st.status = 'ready';
        cb({ status: 'ready', version: B.version, notes: B.notes || [], fresh: true });
      });
    });
  }

  function readyNotes() {
    try { return JSON.parse(ls('ota.readyNotes') || '[]'); } catch (e) { return []; }
  }

  function autoCheck() {
    if (!auto()) return;
    check(function (r) {
