})();

/* ==========================================================================
   app.js — starts the app, switches screens and routes remote-control keys
   ========================================================================== */
var App = (function () {
  var stack = [];          /* history: [{name, params}] */
  var current = null;
  var currentName = '';

  function activate(name, params, returning, result) {
    var all = document.querySelectorAll('.screen');
    for (var i = 0; i < all.length; i++) all[i].style.display = 'none';
    current = Screens[name];
    currentName = name;
    current.el = U.$('scr-' + name);
    current.el.style.display = 'block';
    U.toggleClass(document.body, 'playing', name === 'player');
    if (returning && current.resume) current.resume(result);
    else current.show(params || {});
    UI.tickClock();
  }

  /* opts: {reset:true} clears history, {replace:true} replaces the current screen */
  function go(name, params, opts) {
    if (current && current.hide) current.hide();
    if (opts && opts.reset) stack = [];
    else if (opts && opts.replace) stack.pop();
    stack.push({ name: name, params: params || {} });
    activate(name, params, false);
  }

  function back(result) {
    if (stack.length <= 1) { exitConfirm(); return; }
    if (current && current.hide) current.hide();
    stack.pop();
    var prev = stack[stack.length - 1];
    activate(prev.name, prev.params, true, result);
  }

  function exitConfirm() {
    UI.confirm({
      title: 'الخروج من التطبيق؟',
      buttons: [{ label: 'خروج', value: 'exit', danger: true }, { label: 'إلغاء', value: 'no' }],
      index: 1,
      onSelect: function (v) { if (v === 'exit') exitApp(); }
    });
  }

  function exitApp() {
    Player.stop();
    try { tizen.application.getCurrentApplication().exit(); }
    catch (e) { UI.toast('تعذّر الخروج'); }
  }

  /* ---------------- keys ---------------- */
  function onKeyDown(e) {
    var c = e.keyCode;
    var k = Keys.name(e);
    var ae = document.activeElement;
    var inInput = ae && ae.tagName === 'INPUT';

    if (inInput) {
      /* typing in a text box: only intercept "done", "cancel" and up/down */
      if (k === 'imedone' || c === 13 || c === 40) { e.preventDefault(); dispatch('imedone', e); }
      else if (k === 'imecancel' || c === 10009 || c === 27) { e.preventDefault(); dispatch('imecancel', e); }
      else if (c === 38) { e.preventDefault(); dispatch('imeup', e); }
      return;
    }

    if (!k && c === 8) k = 'back';            /* Backspace on a PC */
    if (k === 'exit') { exitApp(); return; }
    if (!k) return;
    e.preventDefault();
    dispatch(k, e);
  }

  function dispatch(k, e) {
    var m = UI.modal();
    if (m) { m.onKey(k, e); return; }
    if (current && current.onKey) current.onKey(k, e);
  }

  /* ---------------- start-up ---------------- */
  /* the 1920x1080 design fills screens of any shape: on a wide car screen the
     page gets wider (backgrounds stretch, lists and panels keep their size) */
  function fitScreen() {
    var w = window.innerWidth, h = window.innerHeight;
    if (!w || !h) return;
    var W = 1920, r = w / h;
    if (r > 1920 / 1080 + 0.01) W = Math.round(1080 * r);
    var s = Math.min(w / W, h / 1080);
    var app = U.$('app');
    app.style.width = W + 'px';
    var t = 'translate(' + Math.round((w - W * s) / 2) + 'px,' + Math.round((h - 1080 * s) / 2) + 'px) scale(' + s + ')';
    app.style.transform = t;
    app.style.webkitTransform = t;
  }


  function connect() {
    var acc = Store.getAccount();
    if (!acc) { go('login', {}, { reset: true }); return; }
    UI.loading(true, 'جاري الاتصال بالسيرفر...');
    Xtream.login(acc, function (err) {
      UI.loading(false);
      if (!err) { go('home', {}, { reset: true }); return; }
      var msg = Xtream.errorText(err);
      var others = Store.getPlaylists().length > 1;
      if (err.code === 'auth' || err.code === 'expired' || err.code === 'banned' || err.code === 'disabled') {
        if (others) go('playlists', { message: msg + ' — اختر قائمة أخرى' }, { reset: true });
        else go('login', { message: msg }, { reset: true });
        return;
      }
      var btns = [{ label: 'إعادة المحاولة', value: 'retry' }];
      if (others) btns.push({ label: 'تبديل القائمة', value: 'switch' });
      btns.push({ label: 'تعديل الحساب', value: 'edit' });
      UI.confirm({
        title: 'تعذّر الاتصال', text: msg,
        buttons: btns,
        onSelect: function (v) {
          if (v === 'retry') connect();
          else if (v === 'switch') go('playlists', { message: msg }, { reset: true });
          else go('login', { message: msg }, { reset: true });
        }
      });
    });
  }

  function init() {
    if (window.OTA) OTA.start();   /* this version started: keep it, look for updates later */
    fitScreen();
    window.addEventListener('resize', fitScreen);
    Keys.register();
    UI.startClock();
    document.addEventListener('keydown', onKeyDown);
    document.addEventListener('visibilitychange', function () {
      if (current && current.visibility) current.visibility(document.hidden);
    });
    /* restore saved data first, then start the player and log in */
    Store.init(function () { Player.init(); connect(); });
    /* remote diagnostics: is saved data still there after a restart? */
    setTimeout(function () {
      var v = '?';
      try { v = tizen.application.getCurrentApplication().appInfo.version; } catch (e) {}
      Diag.send('boot', 'v' + v + ' code ' + (window.OTA ? OTA.running() + '/' + OTA.from() : '-') + ' ' + Store.debugInfo());
    }, 4000);
  }

  return {
    init: init, go: go, back: back, exitConfirm: exitConfirm, reconnect: connect,
    current: function () { return currentName; }
  };
})();

window.onload = App.init;

/* ==========================================================================
   touch.js — makes the remote-control app usable on a touch screen.
   - tap an item to open it, tap a button to press it
   - drag a list up / down to scroll it
   - press and hold a channel / film / series to add it to the favourites
   - on the video: tap shows / hides the controls; swipe up / down changes
     the channel; swipe left / right jumps back / forward in a film
