  /* ---------------- making a list the active one ---------------- */
  function activate(listEl) {
    var id = listEl.id, n = screenName();
    if (n === 'browse') {
      var b = scr('browse');
      if (id === 'br-side' && b.zone !== 'side') b.setZone('side');
      if (id === 'br-content' && b.items && b.items.length && b.zone !== 'content') b.setZone('content');
    } else if (n === 'series' && id === 'sr-episodes') {
      if (scr('series').zone !== 'episodes') scr('series').setZone('episodes');
