    }
    return false;
  }

  /* ---------------- drag to scroll, swipe on the video ---------------- */
  var g = null;           /* current gesture */
  var lastGesture = 0;    /* time a drag / hold ended: the click that follows is ignored */

  /* distance from one row to the next on the screen (with the gap between rows) */
  function rowHeight(list) {
    var a = list.el.children[0], b = list.el.children[1];
    if (a && b) { var d = b.getBoundingClientRect().top - a.getBoundingClientRect().top; if (d > 4) return d; }
    var h = a ? a.getBoundingClientRect().height : 0;
