  /* when the finger (or the glide) stops between two rows, settle on the nearest one */
  function snap(st) {
    if (!smooth(st) || st.pos === undefined) return;
    var top = Math.floor(st.pos / st.rowH), frac = st.pos - top * st.rowH;
    if (!frac) { shift(st, 0, false); return; }
