  }

  /* move a list / scroll box so that the content follows the finger (dy = finger movement in screen px) */
  function follow(st, dy) {
    if (st.list && smooth(st)) {
      var l = st.list, maxTop = Math.max(0, l.totalRows() - l.rows);
      var pos = U.clamp(st.startTop * st.rowH - dy, 0, maxTop * st.rowH);
      if (pos === st.pos) return false;
      st.pos = pos;
      var top = Math.floor(pos / st.rowH);
      l.scrollTo(top);
      shift(st, pos - top * st.rowH, false);
      return true;
    }
    if (st.list) return st.list.scrollTo(st.startTop - dy / st.rowH);
    if (st.scrollEl) {
