  }

  /* The rows under the finger are redrawn while scrolling. A touch keeps going to the
     element it started on even after that element left the page, and then it no longer
     reaches the document - so the gesture listens on that element itself. */
  function listen(st) {
    st.el.addEventListener('touchmove', onMove, { passive: false });
    st.el.addEventListener('touchend', onEnd, { passive: true });
    st.el.addEventListener('touchcancel', onCancel, { passive: true });
