  function unlisten(st) {
    if (!st || !st.el) return;
    st.el.removeEventListener('touchmove', onMove, { passive: false });
    st.el.removeEventListener('touchend', onEnd, { passive: true });
    st.el.removeEventListener('touchcancel', onCancel, { passive: true });
