  function onCancel() { clearTimeout(onStart.timer); unlisten(g); g = null; }

  function onStart(e) {
    stopFling();
    finishSnap();
    unlisten(g);
    if (e.touches.length !== 1) { g = null; return; }
    var p = e.touches[0], t = e.target;
    if (closest(t, '#tpad') || closest(t, '#tpad-btn')) { g = null; return; }
    var listEl = closest(t, '.vlist');
    var list = listEl && listEl.__vlist && listEl.__vlist.items.length ? listEl.__vlist : null;
    var scrollEl = !list && screenName() === 'settings' && !UI.modal() ? closest(t, '#set-list') : null;
    if (!list && !scrollEl && screenName() === 'playlists' && !UI.modal()) scrollEl = closest(t, '#pls-list');
    g = { x: p.clientX, y: p.clientY, t: t, list: list, scrollEl: scrollEl, moved: false, held: false,
      rowH: list ? rowHeight(list) : 0, startTop: list ? list.top : 0,
      startScroll: scrollEl ? scrollEl.scrollTop : 0, scale: scrollEl ? scaleOf(scrollEl) : 1,
      lscale: list ? scaleOf(list.el) : 1,
      selfClip: !!(list && window.getComputedStyle(list.el).overflow === 'hidden'),
      samples: [{ y: p.clientY, t: U.now() }], firstSample: { y: p.clientY, t: U.now() }, el: t };
