    if (!g.moved) { g.moved = true; clearTimeout(onStart.timer); }
    g.samples.push({ y: p.clientY, t: U.now() });
    if (g.samples.length > 8) g.samples.shift();
    if ((g.list || g.scrollEl) && Math.abs(dy) >= Math.abs(dx) * 0.7) {
      e.preventDefault();
      /* like any phone list: the rows move with the finger, nothing gets selected */
      follow(g, dy);
      if (g.list && screenName() === 'browse' && g.list === scr('browse').list) scr('browse').updateCount();
    }
  }

  /* after a quick flick the list keeps going for a moment and slows down */
  function startFling(st, dy) {
    var s = st.samples, a = s[0], b = s[s.length - 1], now = U.now();
    for (var i = s.length - 1; i >= 0 && now - s[i].t < 220; i--) a = s[i];
    var dt = b.t - a.t, v = dt > 0 ? (b.y - a.y) / dt : 0;     /* px per ms */
    var first = st.firstSample, whole = b.t - first.t;
    if (whole > 0 && whole < 350) v = (b.y - first.y) / whole;  /* a quick flick: its whole speed */
    if (Math.abs(v) < 0.3) return false;
    var last = now;
    fling = { raf: 0 };
    (function step() {
      var t = U.now(), d = Math.min(48, t - last);
      last = t;
      dy += v * d;
      v *= Math.pow(0.95, d / 16);
      var moved = follow(st, dy);
      if (Math.abs(v) < 0.05 || (!moved && (smooth(st) || (st.list && (st.list.top === 0 || st.list.top >= st.list.totalRows() - st.list.rows))))) {
