  }

  function onEnd(e) {
    clearTimeout(onStart.timer);
    if (!g) return;
    var c = e.changedTouches && e.changedTouches[0];
    var dx = c ? c.clientX - g.x : 0, dy = c ? c.clientY - g.y : 0;
    var used = g.held || (g.moved && (g.list || g.scrollEl));
    if (g.moved && (g.list || g.scrollEl) && !g.held) {
      if (c) g.samples.push({ y: c.clientY, t: U.now() });
      if (!startFling(g, dy)) snap(g);
