      var el = closest(e.target, '.k');
      e.preventDefault();
      if (el) press(el.getAttribute('data-k'), el);
    }, { passive: false });
    pad.addEventListener('touchend', function (e) { e.preventDefault(); release(); }, { passive: false });
    pad.addEventListener('touchcancel', release);
    /* mouse (testing on a computer) */
    pad.addEventListener('mousedown', function (e) { var el = closest(e.target, '.k'); if (el) press(el.getAttribute('data-k'), el); });
    pad.addEventListener('mouseup', release);
    pad.addEventListener('click', function (e) { e.stopPropagation(); });
  }

  /* while a film plays with its controls hidden, the car's floating Back / Home buttons step aside */
  var videoOn = false;
  function watchVideo() {
    var on = false;
    try {
      on = screenName() === 'player' && !UI.modal() && !scr('player').osdVisible() &&
        !scr('player').zapOpen && !scr('player').epsOpen && Player.state() !== 'idle';
    } catch (e) { on = false; }
    if (on !== videoOn) {
      videoOn = on;
      try { if (window.AndroidApp && AndroidApp.videoMode) AndroidApp.videoMode(on); } catch (e) {}
    }
  }

  function init() {
    setInterval(watchVideo, 500);
    document.addEventListener('touchstart', onStart, { passive: true });
    document.addEventListener('click', function (e) {
      if (U.now() - lastGesture < 400) { e.preventDefault(); e.stopPropagation(); return; }
      onTap(e);
    }, true);
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
